(7000,'biology',81,1046,2469,'What is the role of $$\\mathrm{NAD}^{+}$$in cellular respiration?<br>','[{"text": "It is a nucleotide source for ATP synthesis.", "isCorrect": false}, {"text": "It functions as an electron carrier.", "isCorrect": true}, {"text": "It functions as an enzyme.", "isCorrect": false}, {"text": "It is the final electron acceptor for anaerobic respiration.", "isCorrect": false}]',1,'In cellular respiration, $$\\mathrm{NAD}^{+}$$ is an electron carrier.',NULL,'Medium','MCQ',2018,'NEET','2026-07-25 18:34:34.081508',NULL),
(7001,'biology',8,152,322,'Flower is complete when it has','[{"text": "Calyx, corolla, androecium and\\ngynoecium", "isCorrect": true}, {"text": "Androecium and gynoecium", "isCorrect": false}, {"text": "Calyx and corolla", "isCorrect": false}, {"text": "Corolla, Androecium and gynoecium", "isCorrect": false}]',0,'Flower is complete when it has calyx, corolla, androecium and gynoecium.',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
