(14071,'chemistry',15,186,405,'The hydrated salt ${\\rm{N}}{{\\rm{a}}_{\\rm{2}}}{\\rm{C}}{{\\rm{O}}_{\\rm{3}}}{\\rm{.x}}{{\\rm{H}}_{\\rm{2}}}{\\rm{O}}$ undergoes 63% loss in mass on heating and becomes anhydrous. The value of x is','[{"text": "10", "isCorrect": true}, {"text": "12", "isCorrect": false}, {"text": "8", "isCorrect": false}, {"text": "18", "isCorrect": false}]',0,'${\\rm{N}}{{\\rm{a}}_{\\rm{2}}}{\\rm{C}}{{\\rm{O}}_{\\rm{3}}}{\\rm{.x}}{{\\rm{H}}_{\\rm{2}}}{{\\rm{O}}_{{\\rm{(s)}}}} \\to {\\rm{N}}{{\\rm{a}}_{\\rm{2}}}{\\rm{C}}{{\\rm{O}}_{{\\rm{3(s)}}}}{\\rm{ + x}}{{\\rm{H}}_{\\rm{2}}}{{\\rm{O}}_{{\\rm{(g)}}}}$<br>${\\rm{Let}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{100}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{g}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{N}}{{\\rm{a}}_{\\rm{2}}}{\\rm{C}}{{\\rm{o}}_{\\rm{3}}}{\\rm{.x}}{{\\rm{H}}_{\\rm{2}}}{\\rm{O}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{be}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{present}}{\\rm{.}}$<br>$\\therefore \\frac{{{\\rm{100}}}}{{{\\rm{106 + 18x}}}}{\\rm{mol}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {{\\rm{H}}_{\\rm{2}}}{\\rm{O}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{formed}}$<br>${\\rm{63 = }}\\frac{{{\\rm{100x}}}}{{{\\rm{106 + 18x}}}}{\\rm{(18)}}$<br>${\\rm{6678 + 1134x = 1800 x}}$<br>${\\rm{666x = 6678}}$<br>${\\rm{x}} \\simeq {\\rm{10}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
