(14515,'chemistry',15,187,410,'The molarity of urea solution in which 0.0100 g of urea, $\\left[ {{{\\left( {{\\rm{N}}{{\\rm{H}}_{\\rm{2}}}} \\right)}_{\\rm{2}}}{\\rm{CO}}} \\right]$ is added to ${\\rm{0}}{\\rm{.3000}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{d}}{{\\rm{m}}^{\\rm{3}}}$  of water at STP is','[{"text": "${\\\\rm{5}}{\\\\rm{.55 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{ - 4}}}}{\\\\rm{M}}$", "isCorrect": true}, {"text": "${\\\\rm{33}}{\\\\rm{.3}}\\\\,{\\\\rm{M}}$", "isCorrect": false}, {"text": "${\\\\rm{3}}{\\\\rm{.33 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{ - 2}}}}\\\\,{\\\\rm{M}}$", "isCorrect": false}, {"text": "${\\\\rm{0}}{\\\\rm{.555M}}$", "isCorrect": false}]',0,'${\\rm{M = }}\\frac{{{\\rm{weight}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{urea}}}}{{{\\rm{molar}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mass}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{urea}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{ \\times }}{{\\rm{V}}_{{\\rm{(L)}}}}}}$<br>${\\rm{Molality = }}\\frac{{{\\rm{0}}{\\rm{.01}}}}{{{\\rm{60 \\times 0}}{\\rm{.3}}}}{\\rm{ = 5}}{\\rm{.55 \\times 1}}{{\\rm{0}}^{{\\rm{ - 4}}}}{\\rm{M}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
