(14772,'chemistry',15,187,410,'The volume of water that must be added to a mixture of 250 mL of 0.6 M HCl and 750 mL of 0.2 M HCl to obtain 0.25 M solution of HCl is','[{"text": "750 mL", "isCorrect": false}, {"text": "100 mL", "isCorrect": false}, {"text": "200 mL", "isCorrect": true}, {"text": "300 mL", "isCorrect": false}]',2,'${{\\rm{M}}_{{\\rm{final}}}}{\\rm{ = }}\\frac{{{{\\rm{M}}_{\\rm{1}}}{{\\rm{V}}_{\\rm{1}}}{\\rm{ + }}{{\\rm{M}}_{\\rm{2}}}{{\\rm{V}}_{\\rm{2}}}}}{{{{\\rm{V}}_{\\rm{1}}}{\\rm{ + }}{{\\rm{V}}_{\\rm{2}}}{\\rm{ + }}{{\\rm{V}}_{{\\rm{water}}}}}}$<br>${\\rm{0}}{\\rm{.25 = }}\\frac{{\\left( {{\\rm{0}}{\\rm{.6 \\times 250}}} \\right){\\rm{ + }}\\left( {{\\rm{0}}{\\rm{.2 \\times 750}}} \\right)}}{{{\\rm{250 + 750 + }}{{\\rm{V}}_{{\\rm{water}}}}}}$<br>${\\rm{So,}}{\\mkern 1mu} {\\mkern 1mu} {{\\rm{V}}_{{\\rm{water}}}}{\\rm{ = 200}}\\,{\\rm{ml}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
