(14828,'chemistry',45,430,858,'The value of ${\\rm{I}}{{\\rm{P}}_{\\rm{1}}}{\\rm{,}}\\,\\,{\\rm{I}}{{\\rm{P}}_{\\rm{2}}}{\\rm{,}}\\,\\,{\\rm{I}}{{\\rm{P}}_{\\rm{3}}}\\,\\,{\\rm{and}}\\,\\,{\\rm{I}}{{\\rm{P}}_{\\rm{4}}}$ of an atom are respectively 7.5 eV, 25.6 eV, 48.6 eV and 170.6 eV. The electronic configuration of the atom will be','[{"text": "${\\\\rm{1}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{p}}^{\\\\rm{6}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{3}}{{\\\\rm{s}}^{\\\\rm{1}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{p}}^{\\\\rm{6}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{3}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{3}}{{\\\\rm{p}}^{\\\\rm{1}}}$", "isCorrect": true}, {"text": "${\\\\rm{1}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{p}}^{\\\\rm{6}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{3}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{3}}{{\\\\rm{p}}^{\\\\rm{3}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{s}}^{\\\\rm{2}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{2}}{{\\\\rm{p}}^{\\\\rm{6}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{3}}{{\\\\rm{s}}^{\\\\rm{2}}}$", "isCorrect": false}]',1,NULL,NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(14829,'chemistry',15,186,405,'What volume of hydrogen gas at 273K and 1atm pressure, will be consumed in obtaining 21.6 g of elemental boron (atomic mass = 10.8) from the reduction of borontrichloride by hydrogen?','[{"text": "22.4 L", "isCorrect": false}, {"text": "67.2 L", "isCorrect": true}, {"text": "89.6 L", "isCorrect": false}, {"text": "44.8 L", "isCorrect": false}]',1,'${\\rm{BC}}{{\\rm{l}}_{\\rm{3}}}{\\rm{ + }}\\left( {\\frac{{\\rm{3}}}{{\\rm{2}}}} \\right){{\\rm{H}}_{\\rm{2}}} \\to \\mathop {{\\rm{ B}}}\\limits_{{\\rm{1mole}}} {\\rm{ + 3HCl}}$<br>No. of moles of B obtained<br>${\\rm{ = }}\\frac{{{\\rm{Wt}}{\\rm{.of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{B}}}}{{{\\rm{At}}{\\rm{.mass}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{B}}}}{\\rm{ = }}\\frac{{{\\rm{21}}{\\rm{.6}}}}{{{\\rm{10}}{\\rm{.8}}}}{\\rm{ = 2}}$<br>${\\rm{1}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mole}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{B = }}\\frac{{\\rm{3}}}{{\\rm{2}}}{\\rm{mole}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {{\\rm{H}}_{\\rm{2}}}$<br>2 mole of B = 3 mole of ${{\\rm{H}}_{\\rm{2}}}{\\rm{ = 3 \\times 22}}{\\rm{.4L}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {{\\rm{H}}_{\\rm{2}}}{\\rm{ = 67}}{\\rm{.2}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{L}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {{\\rm{H}}_{\\rm{2}}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
