(14893,'chemistry',15,186,405,'What is the weight of oxygen required for the complete combustion of 2.8 kg of ethylene?','[{"text": "2.8 kg", "isCorrect": false}, {"text": "6.4 kg", "isCorrect": false}, {"text": "9.6 kg", "isCorrect": true}, {"text": "96 kg", "isCorrect": false}]',2,'${{\\rm{C}}_{\\rm{2}}}{{\\rm{H}}_{\\rm{4}}}{\\rm{ + 3}}{{\\rm{O}}_{\\rm{2}}} \\to {\\rm{2C}}{{\\rm{O}}_{\\rm{2}}}{\\rm{ + 2}}{{\\rm{H}}_{\\rm{2}}}{\\rm{O}}$<br>28 kg of ${C_2}{H_4}$ gives 96 kg of ${{\\rm{O}}_{\\rm{2}}}$<br>2.8 kg of ${{\\rm{C}}_{\\rm{2}}}{{\\rm{H}}_{\\rm{4}}}$ gives $\\frac{{{\\rm{96 \\times 2}}{\\rm{.8}}}}{{{\\rm{28}}}}{\\rm{kg}}$ of ${{\\rm{O}}_{\\rm{2}}}$<br>${\\rm{ = 9}}{\\rm{.6}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{kg}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {{\\rm{O}}_{\\rm{2}}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
