(14931,'chemistry',15,183,402,'How many moles of magnesium phosphate ${\\rm{M}}{{\\rm{g}}_{\\rm{3}}}{\\left( {{\\rm{P}}{{\\rm{O}}_{\\rm{4}}}} \\right)_{\\rm{2}}}$ will contain 0.25 mole of oxygen atoms?','[{"text": "0.02", "isCorrect": false}, {"text": "${\\\\rm{3}}{\\\\rm{.125 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{ - 2}}}}$", "isCorrect": true}, {"text": "${\\\\rm{1}}{\\\\rm{.25 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{ - 2}}}}$", "isCorrect": false}, {"text": "${\\\\rm{2}}{\\\\rm{.5 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{ - 2}}}}$", "isCorrect": false}]',1,'Moles of ${\\rm{M}}{{\\rm{g}}_{\\rm{3}}}{\\left( {{\\rm{P}}{{\\rm{O}}_{\\rm{4}}}} \\right)_{\\rm{2}}}{\\rm{ = }}\\frac{{\\rm{1}}}{{\\rm{8}}}{\\rm{ \\times 0}}{\\rm{.25}}$<br>${\\rm{ = 3}}{\\rm{.125 \\times 1}}{{\\rm{0}}^{{\\rm{ - 2}}}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL);
