(14937,'chemistry',15,183,402,'Which is heaviest?','[{"text": "25 g of Hg", "isCorrect": false}, {"text": "2 mole of ${{\\\\rm{H}}_{\\\\rm{2}}}{\\\\rm{O}}$", "isCorrect": false}, {"text": "2 mole of ${\\\\rm{C}}{{\\\\rm{O}}_{\\\\rm{2}}}$", "isCorrect": true}, {"text": "4 g atom of O", "isCorrect": false}]',2,'(1) wt of Hg = 25 g<br>$\\left( {\\rm{2}} \\right){\\mkern 1mu} {\\mkern 1mu} {\\rm{wt}}{\\rm{.}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {{\\rm{H}}_{\\rm{2}}}{\\rm{O = 2 \\times 18 = 36g}}$<br>${\\rm{(3)}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{wt}}{\\rm{.}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{C}}{{\\rm{O}}_{\\rm{2}}}{\\rm{ = 2 \\times 44 = 88g}}$<br>${\\rm{(4)}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{wt}}{\\rm{.}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{O = 4 \\times 16 = 64g}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
