(14990,'chemistry',45,430,857,'For ${\\rm{N}}{{\\rm{a}}^{\\rm{ + }}}{\\rm{,M}}{{\\rm{g}}^{{\\rm{2 + }}}}{\\rm{,}}{{\\rm{F}}^{\\rm{ - }}}\\,\\,{\\rm{and}}\\,\\,{{\\rm{O}}^{{\\rm{2 - }}}}{\\rm{;}}$ the correct order of increasing ionic radii is:','[{"text": "${{\\\\rm{O}}^{{\\\\rm{2 - }}}}{\\\\rm{ < }}{{\\\\rm{F}}^{\\\\rm{ - }}}{\\\\rm{ < N}}{{\\\\rm{a}}^{\\\\rm{ + }}}{\\\\rm{ < M}}{{\\\\rm{g}}^{{\\\\rm{2 + }}}}$", "isCorrect": false}, {"text": "${\\\\rm{N}}{{\\\\rm{a}}^{\\\\rm{ + }}}{\\\\rm{ < M}}{{\\\\rm{g}}^{{\\\\rm{2 + }}}}{\\\\rm{ < }}{{\\\\rm{F}}^{\\\\rm{ - }}}{\\\\rm{ < }}{{\\\\rm{O}}^{{\\\\rm{2 - }}}}$", "isCorrect": false}, {"text": "${\\\\rm{M}}{{\\\\rm{g}}^{{\\\\rm{2 + }}}}{\\\\rm{ < N}}{{\\\\rm{a}}^{\\\\rm{ + }}}{\\\\rm{ < }}{{\\\\rm{F}}^{\\\\rm{ - }}}{\\\\rm{ < }}{{\\\\rm{O}}^{{\\\\rm{2 - }}}}$", "isCorrect": true}, {"text": "${\\\\rm{M}}{{\\\\rm{g}}^{{\\\\rm{2 + }}}}{\\\\rm{ < }}{{\\\\rm{O}}^{{\\\\rm{2 - }}}}{\\\\rm{ < N}}{{\\\\rm{a}}^{\\\\rm{ + }}}{\\\\rm{ < }}{{\\\\rm{F}}^{\\\\rm{ - }}}$", "isCorrect": false}]',2,'Isoelectronic series: ${\\rm{M}}{{\\rm{g}}^{{\\rm{2 + }}}}{\\rm{ < N}}{{\\rm{a}}^{\\rm{ + }}}{\\rm{ < }}{{\\rm{F}}^{\\rm{ - }}}{\\rm{ < }}{{\\rm{O}}^{{\\rm{2 - }}}}$ For isoelectronic species, ionic radius decreases with increase in atomic number',NULL,'Medium','MCQ',2018,'JEE','2026-07-25 18:34:34.081508',NULL),
(14969,'chemistry',45,430,857,'Which of the following arrangements represents the increasing order (smallest to largest) of ionic radii of the given species ${{\\rm{O}}^{{\\rm{2 - }}}}{\\rm{,}}{{\\rm{S}}^{{\\rm{2 - }}}}{\\rm{,}}{{\\rm{N}}^{{\\rm{3 - }}}}{\\rm{,}}{{\\rm{P}}^{{\\rm{3 - }}}}{\\rm{?}}$','[{"text": "${{\\\\rm{O}}^{{\\\\rm{2 - }}}}{\\\\rm{ < }}{{\\\\rm{N}}^{{\\\\rm{3 - }}}}{\\\\rm{ < }}{{\\\\rm{S}}^{{\\\\rm{2 - }}}}{\\\\rm{ < }}{{\\\\rm{P}}^{{\\\\rm{3 - }}}}$", "isCorrect": true}, {"text": "${{\\\\rm{O}}^{{\\\\rm{2 - }}}}{\\\\rm{ < }}{{\\\\rm{P}}^{{\\\\rm{3 - }}}}{\\\\rm{ < }}{{\\\\rm{N}}^{{\\\\rm{3 - }}}}{\\\\rm{ < }}{{\\\\rm{S}}^{{\\\\rm{2 - }}}}$", "isCorrect": false}, {"text": "${{\\\\rm{N}}^{{\\\\rm{3 - }}}}{\\\\rm{ < }}{{\\\\rm{O}}^{{\\\\rm{2 - }}}}{\\\\rm{ < }}{{\\\\rm{P}}^{{\\\\rm{3 - }}}}{\\\\rm{ < }}{{\\\\rm{S}}^{{\\\\rm{2 - }}}}$", "isCorrect": false}, {"text": "${{\\\\rm{N}}^{{\\\\rm{3 - }}}}{\\\\rm{ < }}{{\\\\rm{S}}^{{\\\\rm{2 - }}}}{\\\\rm{ < }}{{\\\\rm{O}}^{{\\\\rm{2 - }}}}{\\\\rm{ < }}{{\\\\rm{P}}^{{\\\\rm{3 - }}}}$", "isCorrect": false}]',0,'For isoelectronic species ionic radii decreases as the charge on ion decreases. Further on moving down the group ionic radii increases. Hence the correct order is<br>${{\\rm{O}}^{{\\rm{2 - }}}}{\\rm{ < }}{{\\rm{N}}^{{\\rm{3 - }}}}{\\rm{ < }}{{\\rm{S}}^{{\\rm{2 - }}}}{\\rm{ < }}{{\\rm{P}}^{{\\rm{3 - }}}}$',NULL,'Medium','MCQ',2014,'JEE','2026-07-25 18:34:34.081508',NULL),
