(15823,'chemistry',15,187,412,'The number of molecules in $100 \\mathrm{~mL}$ of ${\\rm{0}}{\\rm{.02}}\\,{\\rm{N}}{{\\rm{H}}_{\\rm{2}}}{\\rm{S}}{{\\rm{O}}_{\\rm{4}}}$ is','[{"text": "$6.023 \\\\times 10^{22}$", "isCorrect": false}, {"text": "$6.023 \\\\times 10^{21}$", "isCorrect": false}, {"text": "$6.023 \\\\times 10^{20}$", "isCorrect": true}, {"text": "$6.023 \\\\times 10^{18}$", "isCorrect": false}]',2,'As, normality = molarity$ \\times $ valence factor for ${{\\rm{H}}_2}{\\rm{S}}{{\\rm{O}}_4}$,<br>valence factor for ${{\\rm{H}}_2}{\\rm{S}}{{\\rm{O}}_4} = 2$<br>$\\therefore {\\mkern 1mu} {\\rm{Normality}},{\\rm{N = M}} \\times {\\rm{2}}$<br>${\\rm{or}}\\,{\\rm{M}}\\,{\\rm{ =  }}\\frac{{\\rm{N}}}{{\\rm{2}}}{\\rm{ = }}\\frac{{{\\rm{0}}{\\rm{.02}}}}{{\\rm{2}}}\\,{\\rm{ =  0}}{\\rm{.01M}}$<br>${\\rm{Moles}}{\\mkern 1mu} \\,{\\rm{of}}\\,{{\\rm{H}}_{\\rm{2}}}{\\rm{S}}{{\\rm{O}}_{\\rm{4}}}$<br>$ = \\frac{{0.01 \\times 100}}{{1000}} = 1 \\times {10^{ - 3}}$ mol<br>$\\left[ {\\because {\\text{Molarity = }}\\frac{{{\\text{Number}}\\,\\,{\\mkern 1mu} {\\text{of}}\\,\\,{\\text{moles}}\\,{\\text{ of}}\\,{\\mkern 1mu} {\\text{solute}}}}{{{\\text{Volume}}\\,\\,{\\text{in}}\\,\\,{\\text{solution}}({\\text{in}}{\\mkern 1mu} {\\text{mL}})}} \\times {\\text{1000}}} \\right]$<br>$\\therefore $Number of molecules in 100mL of ${\\rm{0}}{\\rm{.02}}\\,{\\rm{N}}\\,{{\\rm{H}}_{\\rm{2}}}{\\rm{S}}{{\\rm{O}}_{\\rm{4}}}$<br>$ = 1 \\times {10^{ - 3}} \\times {{\\rm{N}}_{\\rm{A}}}$<br>$ = 1 \\times {10^{ - 3}} \\times 6.023 \\times {10^{23}}$<br>$ = 6.023 \\times {10^{20}}{\\rm{ molecules }}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(16558,'chemistry',49,629,1277,'Which can act as buffer?','[{"text": "$\\\\mathrm{NH}_{4} \\\\mathrm{Cl}+\\\\mathrm{HCl}$", "isCorrect": false}, {"text": "$\\\\mathrm{CH}_{3} \\\\mathrm{COOH}+\\\\mathrm{H}_{2} \\\\mathrm{CO}_{3}$", "isCorrect": false}, {"text": "${\\\\text{40 ml  of  0}}{\\\\text{.1 N   NaCN + 20 ml of  0}}{\\\\text{.1 M  HCN}}$", "isCorrect": true}, {"text": "$\\\\mathrm{NaCl}+\\\\mathrm{NaOH}$", "isCorrect": false}]',2,'$\\mathrm {p H=p K_{a}+\\log \\dfrac{[\\text { Salt }]}{[\\text { Acid }]}}$.',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
