(16122,'chemistry',46,446,892,'Using VSEPR theory, predict the species which has square pyramidal shape','[{"text": "${\\\\rm{SnC}}{{\\\\rm{l}}_{\\\\rm{2}}}$", "isCorrect": false}, {"text": "${\\\\rm{CC}}{{\\\\rm{l}}_{\\\\rm{4}}}$", "isCorrect": false}, {"text": "${\\\\rm{S}}{{\\\\rm{O}}_{\\\\rm{3}}}$", "isCorrect": false}, {"text": "${\\\\rm{Br}}{{\\\\rm{F}}_{\\\\rm{5}}}$", "isCorrect": true}]',3,'${\\rm{Br}}{{\\rm{F}}_{\\rm{5}}}$ has square pyramidal geometry.',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(16123,'chemistry',15,187,410,'How many mL of a solution of concentration ${\\mathrm{100 \\, \\mathrm{mg} \\, \\mathrm{Co}^{2+}}}$ per mL is needed to prepare 10 mL of a solution of concentration ${\\mathrm{20 \\,\\,\\mathrm{mg}\\, \\mathrm{Co}^{2+}}}$ per mL .','[{"text": "$\\\\frac{1}{2}$", "isCorrect": false}, {"text": "2", "isCorrect": true}, {"text": "$\\\\frac{1}{4}$", "isCorrect": false}, {"text": "0.1", "isCorrect": false}]',1,'${\\mathrm{M_{1} V_{1}=M_{2} V_{2}}}$ (Atomic weight of ${\\mathrm{\\mathrm{Co}=58.93 \\mathrm{~g}}}$ )<br>${\\frac{{{\\rm{100}}{\\mkern 1mu} \\,{\\rm{mg}}}}{{{\\rm{58}}{\\rm{.93}}{\\mkern 1mu} {\\rm{mg}}}} \\times {{\\rm{V}}_{\\rm{1}}}{\\rm{ = }}\\frac{{{\\rm{20}}{\\mkern 1mu} {\\rm{mg}}}}{{{\\rm{58}}{\\rm{.93}}{\\mkern 1mu} {\\rm{mg}}}} \\times {\\rm{10}}\\,{\\rm{mL}}}$<br>${{{\\rm{V}}_{\\rm{1}}}{\\rm{ = }}\\frac{{{\\rm{20}} \\times {\\rm{10}}}}{{{\\rm{100}}}}{\\rm{ = }}{\\mkern 1mu} {\\mkern 1mu} {\\rm{2}}\\,{\\rm{mL}}}$',NULL,'Hard','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL);
