(16809,'chemistry',48,761,1657,'Assuming ideal behaviour, what is the entropy of mixing $\\left( {{\\rm{\\Delta }}{{\\rm{S}}_{{\\rm{mix }}}}} \\right){\\rm{of}}\\,\\,{\\rm{1\\,mol}}$ of $\\mathrm{\\mathrm{N}_{2(\\mathrm{~g})}}$ with $\\mathrm{1 \\mathrm{~mol}}$ of $\\mathrm{\\mathrm{O}_{2(\\mathrm{~g})}}$ at the same temperature and pressure ?','[{"text": "$\\\\mathrm{0.693 \\\\mathrm{~J} /(\\\\mathrm{K} \\\\mathrm{mol})}$", "isCorrect": false}, {"text": "$\\\\mathrm{1.39 \\\\mathrm{~J} /(\\\\mathrm{K} \\\\mathrm{mol})}$", "isCorrect": false}, {"text": "$\\\\mathrm{5.76 \\\\mathrm{~J} /(\\\\mathrm{K} \\\\mathrm{mol})}$", "isCorrect": false}, {"text": "$\\\\mathrm{11.5 \\\\mathrm{~J} /(\\\\mathrm{K} \\\\mathrm{mol})}$", "isCorrect": true}]',3,'$\\mathrm{\\Delta_{\\text {mixing }} S_{\\text {system }}=-\\mathrm{R}\\left[\\sum n_{i} \\ln \\chi_{i}\\right]}$<br>$ =  - {\\text{R}}\\left[ {1.\\ln \\frac{1}{2} + \\ln \\frac{1}{2}} \\right] = 2{\\text{R}}\\ln 2 = 11.5\\,{\\text{J/}}({\\text{mol}}{\\mkern 1mu} {\\text{K}}).$',NULL,'Hard','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
