(17301,'chemistry',48,756,1631,'Thermodynamic standard conditions of temperature and pressure are','[{"text": "$\\\\mathrm{0^{\\\\circ} \\\\mathrm{C}}$ and $\\\\mathrm{101.3 \\\\mathrm{kPa}}$", "isCorrect": false}, {"text": "$\\\\mathrm{298 \\\\mathrm{~K}}$ and $\\\\mathrm{1 \\\\mathrm{~atm}}$", "isCorrect": true}, {"text": "$\\\\mathrm{273 \\\\mathrm{~K}}$ and $\\\\mathrm{101.3 \\\\mathrm{kPa}}$", "isCorrect": false}, {"text": "${\\\\rm{0^\\\\circ C}}{\\\\mkern 1mu} {\\\\mkern 1mu} {\\\\rm{and}}{\\\\mkern 1mu} {\\\\mkern 1mu} {\\\\rm{1}}\\\\,{\\\\rm{atm}}{\\\\rm{.}}$", "isCorrect": false}]',1,'Thermodynamic standard conditions of temperature and pressure are<br>$\\mathrm{\\mathrm{T}=25^{\\circ} \\mathrm{C}=25+273=298 \\mathrm{~K}}$<br>$\\mathrm{\\mathrm{P}=1}$ atmosphere',NULL,'Easy','MCQ',2007,'KCET','2026-07-25 18:34:34.081508',NULL),
