(19472,'chemistry',49,617,1239,'For the given reaction, choose the correct expression of ${\\mathrm{\\mathrm{\\mathrm{K}_{\\mathrm{C}}}}}$ from the following<br>${\\mathrm{\\mathrm{\\mathrm{Fe}_{(\\mathrm{aq})}^{3+}+\\mathrm{SCN}_{(\\mathrm{aq})}^{-} \\rightleftharpoons\\left[(\\mathrm{FeSCN})_{(\\mathrm{aq})}^{2+}\\right]}}}$','[{"text": "${\\\\mathrm{\\\\mathrm{\\\\mathrm{K}_{\\\\mathrm{C}}=\\\\dfrac{\\\\left[\\\\mathrm{FeSCN}^{2+}\\\\right]^{2}}{\\\\left[\\\\mathrm{Fe}^{3+}\\\\right]\\\\left[\\\\mathrm{SCN}^{-}\\\\right]}}}}$", "isCorrect": false}, {"text": "${\\\\mathrm{\\\\mathrm{\\\\mathrm{K}_{\\\\mathrm{C}}=\\\\dfrac{\\\\left[\\\\mathrm{FeSCN}^{2+}\\\\right]}{\\\\left[\\\\mathrm{Fe}^{3+}\\\\right]^{2}\\\\left[\\\\mathrm{SCN}^{-}\\\\right]^{2}}}}}$", "isCorrect": false}, {"text": "${\\\\mathrm{\\\\mathrm{\\\\mathrm{K}_{\\\\mathrm{C}}=\\\\dfrac{\\\\left[\\\\mathrm{FeSCN}^{2+}\\\\right]}{\\\\left[\\\\mathrm{Fe}^{3+}\\\\right]\\\\left[\\\\mathrm{SCN}^{-}\\\\right]}}}}$", "isCorrect": true}, {"text": "${\\\\mathrm{\\\\mathrm{\\\\mathrm{K}_{\\\\mathrm{C}}=\\\\dfrac{\\\\left[\\\\mathrm{Fe}^{3+}\\\\right]\\\\left[\\\\mathrm{SCN}^{-}\\\\right]}{\\\\left[\\\\mathrm{FeSCN}^{2+}\\\\right]}}}}$", "isCorrect": false}]',2,'${\\mathrm{\\mathrm{\\mathrm{Fe}_{(\\mathrm{aq})}^{3+}+\\mathrm{SCN}_{(\\mathrm{aq})}^{-} \\rightleftharpoons\\left[(\\mathrm{FeSCN})_{(\\mathrm{aq})}^{2+}\\right]}}}$<br>${\\mathrm{\\mathrm{\\therefore \\mathrm{K}_{\\mathrm{C}}=\\dfrac{\\left[(\\mathrm{FeSCN})^{2+}\\right]}{\\left[\\mathrm{Fe}^{3+}\\right]\\left[\\mathrm{SCN}^{-}\\right]}}}}$<br>So, the correct option is (3).',NULL,'Easy','MCQ',2024,'JEE Main','2026-07-25 18:34:34.081508',NULL),
