(20628,'chemistry',55,1237,2986,'Ethyne on treatment with Lindlar\'s catalyst yeilds','[{"text": "", "isCorrect": false}, {"text": "$\\\\mathrm{CH}_{3}-\\\\mathrm{CH}_{2}-\\\\mathrm{CH}_{3}$", "isCorrect": false}, {"text": "$\\\\mathrm{H}_{2} \\\\mathrm{C}=\\\\mathrm{CH}-\\\\mathrm{CH}=\\\\mathrm{CH}_{2}$", "isCorrect": false}, {"text": "$\\\\mathrm{CH}_{2}=\\\\mathrm{CH}_{2}$", "isCorrect": true}]',3,'Reaction of ethyne with hydrogen in the presence of Lindlar\'s catalyst ${{\\text{Pd/BaS}}{{\\text{O}}_{\\text{4}}}}$ produces ethene.<br>$\\mathop {{\\text{CH}} \\equiv {\\text{CH}}}\\limits_{{\\text{Ethyene}}} {\\text{ + }}{{\\text{H}}_{\\text{2}}}\\xrightarrow[{{\\text{Pd/BaS}}{{\\text{O}}_{\\text{4}}}}]{\\begin{subarray}{l}&nbsp;<br>&nbsp; {\\text{Lindlar}} \\\\&nbsp;<br>&nbsp; {\\text{catalyst}}&nbsp;<br>\\end{subarray} }\\mathop {{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{ = C}}{{\\text{H}}_{\\text{2}}}}\\limits_{{\\text{Ethene}}} $',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
