(21189,'chemistry',55,1234,2969,'','[{"text": "$\\\\mathrm{CH}_{3}-\\\\mathrm{CH}_{2}-\\\\mathrm{CH}_{2}-\\\\mathrm{CH}_{2}-\\\\mathrm{CH}_{2}-\\\\mathrm{CH}_{3}$", "isCorrect": false}, {"text": "", "isCorrect": false}, {"text": "", "isCorrect": true}, {"text": "", "isCorrect": false}]',2,'<img src=\'/img/data/chemistry/55_21189_explanation_1.png\' alt=\'Question Image\' style=\'max-width:100%;\' />',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508','chemistry/55_21189_question_1.png'),
(21192,'chemistry',55,1237,2995,'$\\mathrm{CH}_{3}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{OH} \\xrightarrow[\\mathrm{H}_{2} \\mathrm{SO}_{4} / \\Delta]{\\text { Conc. }} \\mathrm{X}$<br>$\\mathrm{CH}_{3}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{Cl} \\xrightarrow[\\Delta]{\\text { alc. } \\mathrm{KOH}} \\mathrm{Y}$<br>Relation between ${\\rm{X \\&  Y}}$ are-','[{"text": "Same product", "isCorrect": false}, {"text": "Position isomers", "isCorrect": true}, {"text": "Both can show geometrical isomerism", "isCorrect": false}, {"text": "Chain isomers", "isCorrect": false}]',1,'$\\mathrm{CH}_{3}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{OH} \\xrightarrow[\\mathrm{H}_{2} \\mathrm{SO}_{4} / \\Delta]{\\text { Conc. }} \\mathrm{X}$<br>$\\mathrm{CH}_{3}-\\underset{\\text { But-2-ene }}{\\mathrm{CH}}=\\mathrm{CH}-\\mathrm{CH}_{3}$<br>$\\mathrm{CH}_{3}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{CH}_{2}-\\mathrm{Cl} \\xrightarrow[\\Delta]{\\text { alc. KOH }}$<br>$\\underset{1-\\text { Butene }}{\\mathrm{CH}_{3}-\\mathrm{CH}_{2}-\\mathrm{CH}=\\mathrm{CH}_{2}}$<br>Both these are position isomers',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(21193,'chemistry',54,1209,2895,'Match Column I with Column II.<br> <br>Choose the correct answer from the options given below:<div class="matching-question"></div>','[{"text": "A - Q ,\\tB - R,\\tC - P,\\t\\tD - S", "isCorrect": false}, {"text": "A - R,\\tB - P,\\tC - S,\\t\\tD - Q", "isCorrect": true}, {"text": "A - R,\\tB - S,\\tC - P,\\t\\tD - Q", "isCorrect": false}, {"text": "A - S,\\tB - R,\\tC - P,\\t\\tD - Q", "isCorrect": false}]',1,'$({\\text{A}} - {\\text{R}})\\,:$ Functional isomers<br><img src=\'/img/data/chemistry/54_21193_explanation_1.png\' alt=\'Question Image\' style=\'max-width:100%;\' /> <br>$({\\text{B}} - {\\text{P}})\\,:$ Metamers<br><img src=\'/img/data/chemistry/54_21193_explanation_2.png\' alt=\'Question Image\' style=\'max-width:100%;\' /> <br>$({\\text{C}} - {\\text{S}})\\,:$ Tautomers<br><img src=\'/img/data/chemistry/54_21193_explanation_3.png\' alt=\'Question Image\' style=\'max-width:100%;\' /> <br>$({\\text{D}} - {\\text{Q}})\\,:$ Position isomers<br><img src=\'/img/data/chemistry/54_21193_explanation_4.png\' alt=\'Question Image\' style=\'max-width:100%;\' />',NULL,'Hard','Match the following',2023,'JEE','2026-07-25 18:34:34.081508','chemistry/54_21193_question_1.png'),
