(22027,'chemistry',58,174,382,'Calculate the molal depression constant of naphthalene in usual units if enthalpy of fusion is ${\\rm{19192}}{\\rm{.3}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{J}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}$. Pure naphthalene melts at 353.1 K. Molecular mass of naphthalene is<br>${\\rm{128 \\times 1}}{{\\rm{0}}^{{\\rm{ - 3}}}}{\\rm{kg}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}{\\mkern 1mu} {\\mkern 1mu} \\left( {{\\rm{R = 8}}{\\rm{.314}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{J}}{{\\rm{K}}^{{\\rm{ - 1}}}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}} \\right)$','[{"text": "1.86", "isCorrect": false}, {"text": "6.9", "isCorrect": true}, {"text": "5.12", "isCorrect": false}, {"text": "12.8", "isCorrect": false}]',1,NULL,NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22031,'chemistry',58,173,381,'Equimolal solutions of two non - electrolytes in the same solvent have:','[{"text": "different b.pt. and different f.pt.", "isCorrect": false}, {"text": "same b.pt. and same f.pt.", "isCorrect": true}, {"text": "same b.pt. but different f.pt.", "isCorrect": false}, {"text": "different b.pt. but same f.pt.", "isCorrect": false}]',1,'${\\rm{\\Delta T = }}{{\\rm{K}}_{\\rm{f}}}{\\rm{ \\times molality,}}$<br>${{\\rm{K}}_{\\rm{f}}}$ is common for both thus, same $\\Delta {T_f}$<br>${\\rm{\\Delta }}{{\\rm{T}}_{\\rm{b}}}{\\rm{ = }}{{\\rm{K}}_{\\rm{b}}}{\\rm{ \\times molality,}}$<br>${{\\rm{K}}_{\\rm{b}}}$ is common for both thus, same ${\\rm{\\Delta }}{{\\rm{T}}_{\\rm{b}}}$.',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22035,'chemistry',58,172,380,'The vapour pressure of water is 12.3kPa at 300K. Calculate the vapour pressure 1 molal solution of a non-volatile solute in it.','[{"text": "12.08 kPa", "isCorrect": true}, {"text": "2.03kPa", "isCorrect": false}, {"text": "2.4kPa", "isCorrect": false}, {"text": "0.4kPa", "isCorrect": false}]',0,'$\\frac{{{\\rm{P^\\circ  - }}{{\\rm{P}}_{\\rm{S}}}}}{{{\\rm{P^\\circ }}}}{\\rm{ = }}\\frac{{{{\\rm{w}}_{\\rm{2}}}{\\rm{ \\times M}}{{\\rm{w}}_{\\rm{1}}}}}{{{\\rm{M}}{{\\rm{w}}_{\\rm{2}}}{\\rm{ \\times }}{{\\rm{w}}_{\\rm{1}}}}}$<br>${\\rm{ = }}\\frac{{{\\rm{m \\times M}}{{\\rm{w}}_{\\rm{1}}}}}{{{\\rm{1000}}}}$<br>$\\frac{{{\\rm{12}}{\\rm{.3 - P}}}}{{{\\rm{12}}{\\rm{.3}}}}{\\rm{ = }}\\frac{{{\\rm{1 \\times 18}}}}{{{\\rm{1000}}}}$<br>${\\rm{P = 12}}{\\rm{.08}}\\,\\,{\\rm{kPa}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
