(22193,'chemistry',58,176,385,'If the observed and theoretical molecular mass of NaCl is found to be 31.80 and 58.50, then the degree of dissociation of NaCl is','[{"text": "$83.96\\\\% $", "isCorrect": true}, {"text": "$8.39\\\\% $", "isCorrect": false}, {"text": "$90\\\\% $", "isCorrect": false}, {"text": "$100\\\\% $", "isCorrect": false}]',0,'${\\rm{Van\'t Hoff}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{factor,i = }}\\frac{{{\\rm{Theoretical}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{molecular}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mass}}}}{{{\\rm{Observed}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{molecular}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mass}}}}$<br>${\\rm{ = }}\\frac{{{\\rm{58}}{\\rm{.5}}}}{{{\\rm{31}}{\\rm{.80}}}}{\\rm{ = 1}}{\\rm{.8396}}$<br>Degree of dissociation,<br>${\\rm{\\alpha  = }}\\frac{{{\\rm{i - 1}}}}{{{\\rm{n - 1}}}}{\\rm{ = }}\\frac{{{\\rm{1}}{\\rm{.8396 - 1}}}}{{{\\rm{2 - 1}}}}{\\rm{ = 0}}{\\rm{.8396}}$<br>${\\rm{\\% \\alpha  = 83}}{\\rm{.96\\% }}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
