(22347,'chemistry',59,372,694,'Limiting molar conductivity of ${\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{OH,}}\\,\\,{\\rm{i}}{\\rm{.e}}{\\rm{.,}}$ ${\\rm{\\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{OH}}} \\right)$','[{"text": "${\\\\rm{\\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}} \\\\right){\\\\rm{ + \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{NaCl}}} \\\\right){\\\\rm{ - \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{NaOH}}} \\\\right)$", "isCorrect": false}, {"text": "${\\\\rm{\\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{OH}}} \\\\right){\\\\rm{ + \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{NaCl}}} \\\\right){\\\\rm{ - \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}} \\\\right)$", "isCorrect": false}, {"text": "${\\\\rm{\\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{OH}}} \\\\right){\\\\rm{ + \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}} \\\\right){\\\\rm{ - \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{HCl}}} \\\\right)$", "isCorrect": false}, {"text": "${\\\\rm{\\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}} \\\\right){\\\\rm{ + \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{NaOH}}} \\\\right){\\\\rm{ - \\\\Lambda }}_{\\\\rm{m}}^{\\\\rm{o}}\\\\left( {{\\\\rm{NaCl}}} \\\\right)$", "isCorrect": true}]',3,'${\\rm{\\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}}} \\right){\\rm{ = \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{NH}}_{\\rm{4}}^{\\rm{ + }}} \\right){\\rm{ + \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{C}}{{\\rm{l}}^{\\rm{ - }}}} \\right)\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,{\\rm{(1)}}$<br>${\\rm{\\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{NaOH}}} \\right){\\rm{ = \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{N}}{{\\rm{a}}^{\\rm{ + }}}} \\right){\\rm{ + \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{O}}{{\\rm{H}}^{\\rm{ - }}}} \\right)\\,\\,\\,\\,\\,\\,\\,\\,\\,{\\rm{(2)}}$<br>${\\rm{\\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{NaCl}}} \\right){\\rm{ = \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{N}}{{\\rm{a}}^{\\rm{ + }}}} \\right){\\rm{ + \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{C}}{{\\rm{l}}^{\\rm{ - }}}} \\right)\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,{\\rm{(3)}}$<br>${\\rm{From}}\\,\\,{\\rm{(1),}}\\,\\,{\\rm{(2),}}\\,\\,{\\rm{(3)}}$<br>${\\rm{\\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}}} \\right){\\rm{ = \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{NH}}_{\\rm{4}}^{\\rm{ + }}} \\right){\\rm{ + \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{C}}{{\\rm{l}}^{\\rm{ - }}}} \\right)$<br>${\\rm{ = \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}}} \\right){\\rm{ + \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{NaOH}}} \\right){\\rm{ - \\Lambda }}_{\\rm{m}}^{\\rm{o}}\\left( {{\\rm{NaCl}}} \\right)$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
