(22349,'chemistry',54,1214,2911,'The correct stability order of carbocations is','[{"text": "${\\\\left( {{\\\\rm{C}}{{\\\\rm{H}}_3}} \\\\right)_3}\\\\mathop {\\\\rm{C}}\\\\limits^ +   > {\\\\left( {{\\\\rm{C}}{{\\\\rm{H}}_3}} \\\\right)_2}\\\\mathop {\\\\rm{C}}\\\\limits^ +  {\\\\rm{H}} > {\\\\rm{C}}{{\\\\rm{H}}_3} - \\\\mathop {\\\\rm{C}}\\\\limits^ +  {{\\\\rm{H}}_2} > \\\\mathop {\\\\rm{C}}\\\\limits^ +  {{\\\\rm{H}}_3}$", "isCorrect": true}, {"text": "", "isCorrect": false}, {"text": "$\\\\mathop {\\\\rm{C}}\\\\limits^ +  {{\\\\rm{H}}_3} > {\\\\left( {{\\\\rm{C}}{{\\\\rm{H}}_3}} \\\\right)_2}\\\\mathop {\\\\rm{C}}\\\\limits^ +  {\\\\rm{H}} > {\\\\rm{C}}{{\\\\rm{H}}_3} - \\\\mathop {\\\\rm{C}}\\\\limits^ +  {{\\\\rm{H}}_2} > {\\\\left( {{\\\\rm{C}}{{\\\\rm{H}}_3}} \\\\right)_3}\\\\mathop {\\\\rm{C}}\\\\limits^ +  $", "isCorrect": false}, {"text": "${\\\\left( {{\\\\rm{C}}{{\\\\rm{H}}_3}} \\\\right)_3}\\\\mathop {\\\\rm{C}}\\\\limits^ +   > {\\\\rm{C}}{{\\\\rm{H}}_3} - \\\\mathop {\\\\rm{C}}\\\\limits^ +  {{\\\\rm{H}}_2} > {\\\\left( {{\\\\rm{C}}{{\\\\rm{H}}_3}} \\\\right)_2}\\\\mathop {\\\\rm{C}}\\\\limits^ +  {\\\\rm{H}} > \\\\mathop {\\\\rm{C}}\\\\limits^ +  {{\\\\rm{H}}_3}$", "isCorrect": false}]',0,'Alkyl groups directly attached to the positively charged carbon stabilise the carbocations due to inductive (${\\rm{ + I}}$) and hyperconjugation effects. Larger the number of alkyl groups attached to the carbon atom carrying positive charge, higher is the stability. Thus, the stability order will be<br>$\\left(\\mathrm{CH}_{3}\\right)_{3} \\stackrel{+}{\\mathrm{C}}>\\left(\\mathrm{CH}_{3}\\right)_{2} \\stackrel{+}{\\mathrm{C}} \\mathrm{H}>\\mathrm{CH}_{3} \\stackrel{+}{\\mathrm{C}} \\mathrm{H}_{2}>\\stackrel{+}{\\mathrm{C}} \\mathrm{H}_{3} .$<br>So, the correct option is (1).',NULL,'Easy','MCQ',2024,'JEE Main','2026-07-25 18:34:34.081508',NULL),
(22350,'chemistry',58,173,381,'The ratio of difference in boiling point of a solution and that of pure solvent to its molality is known as','[{"text": "elevation in boiling point", "isCorrect": false}, {"text": "cryoscopic constant", "isCorrect": false}, {"text": "depression in freezing point", "isCorrect": false}, {"text": "molal elevation constant", "isCorrect": true}]',3,'${{\\rm{T}}_{\\rm{b}}}{\\rm{ - T}}_{\\rm{b}}^{\\rm{0}}{\\rm{ = }}{{\\rm{K}}_{\\rm{b}}}{\\rm{m}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22351,'chemistry',59,370,691,'The resistance of 0.01 N solution of an electrolyte was found to be 220 ohm at 298 K using a conductivity cell with a cell constant of ${\\rm{0}}{\\rm{.88c}}{{\\rm{m}}^{{\\rm{ - 1}}}}$. The value of equivalent conductance of solution is','[{"text": "${\\\\rm{400}}\\\\,\\\\,{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{g}}\\\\,\\\\,{\\\\rm{e}}{{\\\\rm{q}}^{{\\\\rm{ - 1}}}}$", "isCorrect": true}, {"text": "${\\\\rm{295}}\\\\,\\\\,{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{g}}\\\\,\\\\,{\\\\rm{e}}{{\\\\rm{q}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{419}}\\\\,\\\\,{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{g}}\\\\,\\\\,{\\\\rm{e}}{{\\\\rm{q}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{425}}\\\\,\\\\,{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{g}}\\\\,\\\\,{\\\\rm{e}}{{\\\\rm{q}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}]',0,'${{\\rm{\\Lambda }}_{{\\rm{eq}}}}{\\rm{ = \\kappa  \\times }}\\frac{{{\\rm{1000}}}}{{\\rm{N}}}{\\rm{ = }}\\frac{{\\rm{1}}}{{\\rm{R}}}{\\rm{ \\times }}\\frac{{\\rm{l}}}{{\\rm{A}}}{\\rm{ \\times }}\\frac{{{\\rm{1000}}}}{{\\rm{N}}}$<br>${\\rm{ = }}\\frac{{\\rm{1}}}{{\\rm{R}}}{\\rm{ \\times cell}}\\,\\,{\\rm{constant \\times }}\\frac{{{\\rm{1000}}}}{{\\rm{N}}}{\\rm{ = }}\\frac{{\\rm{1}}}{{{\\rm{220}}}}{\\rm{ \\times 0}}{\\rm{.88 \\times }}\\frac{{{\\rm{1000}}}}{{{\\rm{0}}{\\rm{.01}}}}$<br>${\\rm{ = 400}}\\,\\,{\\rm{oh}}{{\\rm{m}}^{{\\rm{ - 1}}}}\\,\\,{\\rm{c}}{{\\rm{m}}^{\\rm{2}}}{\\rm{g}}\\,\\,{\\rm{e}}{{\\rm{q}}^{{\\rm{ - 1}}}}$',NULL,'Hard','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22353,'chemistry',54,1214,2917,'A species having carbon with sextet of electrons and can act as electrophile is','[{"text": "carbanion", "isCorrect": false}, {"text": "carbon free radical", "isCorrect": false}, {"text": "carbocation", "isCorrect": true}, {"text": "pentavalent carbon.", "isCorrect": false}]',2,'Carbocation has sextet of electrons. It has incomplete octet. So it is an electrophile. <img src=\'/img/data/chemistry/54_22353_explanation_1.png\' alt=\'Question Image\' style=\'max-width:100%;\' />  Carbocation is formed during heterolytic cleavage. So, the correct option is (3).',NULL,'Easy','MCQ',2024,'JEE Main','2026-07-25 18:34:34.081508',NULL),
(22354,'chemistry',58,173,381,'If the elevation in boiling point of a solution of 10 g of solute (mol. wt. = 100) in 100 g of water is $\\Delta {T_b}$, the ebullioscopic constant of water is','[{"text": "10", "isCorrect": false}, {"text": "${\\\\rm{10\\\\Delta }}{{\\\\rm{T}}_{\\\\rm{b}}}$", "isCorrect": false}, {"text": "${\\\\rm{\\\\Delta }}{{\\\\rm{T}}_{\\\\rm{b}}}$", "isCorrect": true}, {"text": "$\\\\frac{{{\\\\rm{\\\\Delta }}{{\\\\rm{T}}_{\\\\rm{b}}}}}{{{\\\\rm{10}}}}$", "isCorrect": false}]',2,'${\\rm{\\Delta }}{{\\rm{T}}_{\\rm{b}}}{\\rm{ = }}\\frac{{{{\\rm{K}}_{\\rm{b}}}{\\rm{ \\times }}{{\\rm{w}}_{\\rm{2}}}{\\rm{ \\times 1000}}}}{{{\\rm{m}}{{\\rm{w}}_{\\rm{2}}}{\\rm{ \\times }}{{\\rm{w}}_{\\rm{1}}}}}{\\rm{;}}$<br>$\\therefore {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {{\\rm{K}}_{\\rm{b}}}{\\rm{ = }}\\frac{{{\\rm{\\Delta }}{{\\rm{T}}_{\\rm{b}}}{\\rm{ \\times 100 \\times 100}}}}{{{\\rm{10 \\times 1000}}}}{\\rm{ = \\Delta }}{{\\rm{T}}_{\\rm{b}}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22355,'chemistry',59,370,690,'If resistivity of 0.8 M KCl solution is ${\\rm{2}}{\\rm{.5 \\times 1}}{{\\rm{0}}^{{\\rm{ - 3}}}}{\\rm{ohm}}\\,\\,{\\rm{cm}}$. The molar conductivity of solution is','[{"text": "${\\\\rm{2 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{5}}}{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{5 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{5}}}{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": true}, {"text": "${\\\\rm{4 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{5}}}{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{3 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{5}}}{\\\\rm{oh}}{{\\\\rm{m}}^{{\\\\rm{ - 1}}}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{2}}}{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}]',1,'Given,<br>Resistivity $\\left( {\\rm{\\rho }} \\right){\\rm{ = 2}}{\\rm{.5 \\times 1}}{{\\rm{0}}^{{\\rm{ - 3}}}}{\\rm{ohm cm}}$<br>${\\rm{M = 0}}{\\rm{.8}}\\,\\,{\\rm{M}}$<br>We know that,<br>${\\rm{\\kappa  = }}\\frac{{\\rm{1}}}{{\\rm{\\rho }}}{\\rm{ = }}\\frac{{\\rm{1}}}{{{\\rm{2}}{\\rm{.5 \\times 1}}{{\\rm{0}}^{{\\rm{ - 3}}}}}}$<br>${\\rm{ = 4 \\times 1}}{{\\rm{0}}^{\\rm{2}}}{\\rm{ohm}}\\,\\,{\\rm{c}}{{\\rm{m}}^{{\\rm{ - 1}}}}$<br>Also, molar conductivity $\\left( {{{\\rm{\\Lambda }}_{\\rm{m}}}} \\right){\\rm{ = \\kappa  \\times }}\\frac{{{\\rm{1000}}}}{{\\rm{M}}}$<br>${\\rm{ = }}\\frac{{{\\rm{4 \\times 1}}{{\\rm{0}}^{\\rm{2}}}{\\rm{ \\times 1000}}}}{{{\\rm{0}}{\\rm{.8}}}}$<br>${{\\rm{\\Lambda }}_{\\rm{m}}}{\\rm{ = 5 \\times 1}}{{\\rm{0}}^{\\rm{5}}}{\\rm{oh}}{{\\rm{m}}^{{\\rm{ - 1}}}}\\,\\,{\\rm{c}}{{\\rm{m}}^{\\rm{2}}}{\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}$',NULL,'Medium','MCQ',2020,'MHTCET','2026-07-25 18:34:34.081508',NULL),
(22358,'chemistry',58,173,381,'A solution containing 0.1 g of a non-volatile organic substance P(molecular mass 100) in 100 g of benzene raises the boiling point of benzene by ${\\rm{0}}{\\rm{.2^\\circ C}}$, while a solution containing 0.1 g of another non-volatile substance Q in the same amount of benzene raises the boiling point of benzene by ${\\rm{0}}{\\rm{.4^\\circ C}}$. What is the ratio of molecular masses of P and Q?','[{"text": "${\\\\rm{1:4}}$", "isCorrect": false}, {"text": "${\\\\rm{2:1}}$", "isCorrect": true}, {"text": "${\\\\rm{1:2}}$", "isCorrect": false}, {"text": "${\\\\rm{4:1}}$", "isCorrect": false}]',1,'$\\frac{{{{\\left( {{\\rm{\\Delta T}}} \\right)}_{\\rm{P}}}}}{{{{\\left( {{\\rm{\\Delta T}}} \\right)}_{\\rm{Q}}}}}{\\rm{ = }}\\frac{{{{\\rm{K}}_{\\rm{b}}}{\\rm{ \\times }}{{\\left( {\\frac{{{{\\rm{w}}_{\\rm{2}}}{\\rm{ \\times 1000}}}}{{{{\\rm{m}}_{\\rm{2}}}{\\rm{ \\times }}{{\\rm{w}}_{\\rm{1}}}}}} \\right)}_{\\rm{P}}}}}{{{{\\rm{K}}_{\\rm{b}}}{\\rm{ \\times }}{{\\left( {\\frac{{{{\\rm{w}}_{\\rm{2}}}{\\rm{ \\times 1000}}}}{{{{\\rm{m}}_{\\rm{2}}}{\\rm{ \\times }}{{\\rm{w}}_{\\rm{1}}}}}} \\right)}_{\\rm{Q}}}}}$<br>$\\frac{{{\\rm{0}}{\\rm{.2}}}}{{{\\rm{0}}{\\rm{.4}}}}{\\rm{ = }}\\frac{{{{\\left( {\\frac{{{\\rm{0}}{\\rm{.1 \\times 1000}}}}{{{\\rm{100 \\times 100}}}}} \\right)}_{\\rm{P}}}}}{{{{\\left( {\\frac{{{\\rm{0}}{\\rm{.1 \\times 1000}}}}{{{\\rm{100 \\times }}{{\\rm{m}}_{\\rm{2}}}}}} \\right)}_{\\rm{Q}}}}}$<br>$\\left[ {{\\rm{Let}}{{\\left( {{{\\rm{m}}_{\\rm{2}}}} \\right)}_{\\rm{P}}}{\\rm{ = 100}}} \\right]$<br>$\\frac{{\\rm{1}}}{{\\rm{2}}}{\\rm{ = }}\\frac{{{{\\left( {{{\\rm{m}}_{\\rm{2}}}} \\right)}_{\\rm{Q}}}}}{{{\\rm{100}}}} \\Rightarrow {\\left( {{{\\rm{m}}_{\\rm{2}}}} \\right)_{\\rm{Q}}}{\\rm{ = 50}}$<br>$\\therefore {\\left( {{{\\rm{m}}_{\\rm{2}}}} \\right)_{\\rm{P}}}{\\rm{:}}{\\left( {{{\\rm{m}}_{\\rm{2}}}} \\right)_{\\rm{Q}}}{\\rm{ = 100:50 = 2:1}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22359,'chemistry',59,370,690,'What will be the concentration of NaCl solution, if the molar conductivity and conductivity of NaCl solution is ${\\rm{124}}{\\rm{.3}}{{\\rm{\\Omega }}^{{\\rm{ - 1}}}}{\\rm{c}}{{\\rm{m}}^{\\rm{2}}}{\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}$ and ${\\rm{1}}{\\rm{.243 \\times 1}}{{\\rm{0}}^{{\\rm{ - 4}}}}{{\\rm{\\Omega }}^{{\\rm{ - 1}}}}{\\rm{c}}{{\\rm{m}}^{\\rm{2}}}$ respectively?','[{"text": "${\\\\rm{0}}{\\\\rm{.1}}\\\\,\\\\,{\\\\rm{mol}}\\\\,\\\\,{{\\\\rm{L}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{0}}{\\\\rm{.001}}\\\\,\\\\,{\\\\rm{mol}}\\\\,\\\\,{{\\\\rm{L}}^{{\\\\rm{ - 1}}}}$", "isCorrect": true}, {"text": "${\\\\rm{0}}{\\\\rm{.01}}\\\\,\\\\,{\\\\rm{mol}}\\\\,\\\\,{{\\\\rm{L}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{0}}{\\\\rm{.02}}\\\\,\\\\,{\\\\rm{mol}}\\\\,\\\\,{{\\\\rm{L}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}]',1,'Given,<br>Molar conductivity $\\left( {{{\\rm{\\Lambda }}_{\\rm{m}}}} \\right){\\rm{ = 124}}{\\rm{.3}}{{\\rm{\\Omega }}^{{\\rm{ - 1}}}}{\\rm{c}}{{\\rm{m}}^{\\rm{2}}}{\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}$<br>Conductivity $\\left( {\\rm{\\kappa }} \\right){\\rm{ = 1}}{\\rm{.243 \\times 1}}{{\\rm{0}}^{{\\rm{ - 4}}}}{{\\rm{\\Omega }}^{{\\rm{ - 1}}}}{\\rm{c}}{{\\rm{m}}^{\\rm{2}}}$<br>We know that,<br>Molar conductivity $\\left( {{{\\rm{\\Lambda }}_{\\rm{m}}}} \\right){\\rm{ = }}\\frac{{{\\rm{\\kappa  \\times 1000}}}}{{\\rm{M}}}$<br>${\\rm{M = }}\\frac{{{\\rm{\\kappa  \\times 1000}}}}{{{{\\rm{\\Lambda }}_{\\rm{m}}}}}$<br>${\\rm{ = }}\\frac{{{\\rm{1}}{\\rm{.243 \\times 1}}{{\\rm{0}}^{{\\rm{ - 4}}}}{\\rm{ \\times 1000}}}}{{{\\rm{124}}{\\rm{.3}}}}$<br>${\\rm{ = 0}}{\\rm{.001}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mol}}\\,\\,{{\\rm{L}}^{{\\rm{ - 1}}}}$.',NULL,'Easy','MCQ',2020,'MHTCET','2026-07-25 18:34:34.081508',NULL),
(22360,'chemistry',55,1239,3007,'Amongst the following, the total number of compounds which will undergo addition reaction will be:<br>(A) ${\\mathrm{\\mathrm{CH}_{3}-\\mathrm{CH}=\\mathrm{CH}_{2}}}$ <br>(B) (C) ${\\text{C}}{{\\text{H}}_{\\text{3}}} - {\\text{C}} \\equiv {\\text{N}}$ <br>(D) (E) ${\\mathrm{\\mathrm{CH}_{4}}}$<br>(F) ${\\mathrm{\\mathrm{CH}_{3} \\mathrm{C} \\equiv \\mathrm{CCH}_{3}}}$','[{"text": "5", "isCorrect": true}, {"text": "6", "isCorrect": false}, {"text": "1", "isCorrect": false}, {"text": "3", "isCorrect": false}]',0,'Compounds containing unsaturated bonds (double or triple bonds) will undergo addition reaction. Thus, except ${\\mathrm{\\mathrm{CH}_{4}}}$ all will show addition reaction.<br>(Total number of compounds ${\\mathrm{=\\mathrm{A}+\\mathrm{B}+\\mathrm{C}+\\mathrm{D}+\\mathrm{F}=5}}$ )',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508','chemistry/55_22360_question_1.png'),
(22362,'chemistry',58,172,380,'A 12 g of nonvolatile solute dissolved in 108 g of water produces the relative lowering vapour pressure 0.1. The molecular mass of the solute is','[{"text": "20", "isCorrect": true}, {"text": "40", "isCorrect": false}, {"text": "60", "isCorrect": false}, {"text": "80", "isCorrect": false}]',0,'${\\rm{RLVP = }}\\frac{{\\left( {{{\\rm{w}}_{\\rm{2}}}} \\right)\\left( {{\\rm{m}}{{\\rm{w}}_{\\rm{1}}}} \\right)}}{{\\left( {{\\rm{m}}{{\\rm{w}}_{\\rm{2}}}} \\right)\\left( {{{\\rm{w}}_{\\rm{1}}}} \\right)}}$<br>${\\rm{0}}{\\rm{.1 = }}\\frac{{\\left( {{\\rm{12}}} \\right)\\left( {{\\rm{18}}} \\right)}}{{\\left( {{\\rm{m}}{{\\rm{w}}_{\\rm{2}}}} \\right){\\rm{108}}}}$<br>$\\left( {{\\rm{m}}{{\\rm{w}}_{\\rm{2}}}} \\right){\\rm{ = 20}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22363,'chemistry',59,371,693,'Which of the following electrolytic solutions has the least specific conductance?','[{"text": "2 N", "isCorrect": true}, {"text": "0.002 N", "isCorrect": false}, {"text": "0.02 N", "isCorrect": false}, {"text": "0.2 N", "isCorrect": false}]',0,'Specific conductance of electrolytic solution varies with the concentration of the electrolyte. In general specific conductance of an electrolyte increases with decrease in concentration or increase in dilution. So, electrolytic solution of concentration 2 N has least specific',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22366,'chemistry',58,172,380,'Which of the following solutions have more lowering in vapour pressure at a certain temperature?','[{"text": "90 grams of glucose in 900 grams of ${{\\\\rm{H}}_{\\\\rm{2}}}{\\\\rm{O}}$", "isCorrect": true}, {"text": "34.2 grams of sucrose in 450 grams of ${{\\\\rm{H}}_{\\\\rm{2}}}{\\\\rm{O}}$", "isCorrect": false}, {"text": "20 grams of urea in 900 grams of ${{\\\\rm{H}}_{\\\\rm{2}}}{\\\\rm{O}}$", "isCorrect": false}, {"text": "45 grams of glucose in 900 grams of ${{\\\\rm{H}}_{\\\\rm{2}}}{\\\\rm{O}}$", "isCorrect": false}]',0,'Determine the mole fraction for all the solutions.',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22367,'chemistry',59,371,693,'The pair of electrolytes that posses same value for the constant (A) in the Debye - Huckel - Onsagar equation, ${{\\rm{\\Lambda }}_{\\rm{m}}}{\\rm{ = \\Lambda }}_{\\rm{m}}^{\\rm{o}}{\\rm{ = A}}\\sqrt {\\rm{C}} $','[{"text": "${\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl,}}\\\\,\\\\,{\\\\rm{NaBr}}$", "isCorrect": true}, {"text": "${\\\\rm{NaBr,}}\\\\,\\\\,{\\\\rm{MgS}}{{\\\\rm{O}}_{\\\\rm{4}}}$", "isCorrect": false}, {"text": "${\\\\rm{NaCl,}}\\\\,\\\\,{\\\\rm{CaC}}{{\\\\rm{l}}_{\\\\rm{2}}}$", "isCorrect": false}, {"text": "${\\\\rm{MgS}}{{\\\\rm{O}}_{\\\\rm{4}}}{\\\\rm{,}}\\\\,\\\\,{\\\\rm{N}}{{\\\\rm{a}}_{\\\\rm{2}}}{\\\\rm{S}}{{\\\\rm{O}}_{\\\\rm{4}}}$", "isCorrect": false}]',0,'In Debye - Huckel Onsagar equation, the value of constant A depends on nature of electrolytes i.e., charge on cation and anion produced by dissociation of electrolytes in the solution.<br>${\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}}\\,\\,{\\rm{and}}\\,\\,{\\rm{NaBr}}$ on dissociation gives 2 ions each.<br>${\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}} \\to {\\rm{NH}}_{\\rm{4}}^{\\rm{ + }}{\\rm{ + C}}{{\\rm{l}}^{\\rm{ - }}}$<br>${\\rm{NaBr}} \\to {\\rm{N}}{{\\rm{a}}^{\\rm{ + }}}{\\rm{ + B}}{{\\rm{r}}^{\\rm{ - }}}$<br>Therefore, they give same value for the constant (A).',NULL,'Medium','MCQ',2020,'KCET','2026-07-25 18:34:34.081508',NULL),
(22370,'chemistry',58,172,380,'The vapour pressure of methanol at certain temperature is 1 atm. By adding a small amount of ethyl acetate the vapour pressure of the solution is found to be 684 mm. The relative lowering of vapour pressure is','[{"text": "0.1", "isCorrect": true}, {"text": "0.9", "isCorrect": false}, {"text": "76", "isCorrect": false}, {"text": "0.694", "isCorrect": false}]',0,'Relative lowering of vapour pressure<br>$\\frac{{{{\\rm{P}}^{\\rm{0}}}{\\rm{ - P}}}}{{{{\\rm{P}}^{\\rm{0}}}}}{\\rm{ = }}\\frac{{{\\rm{760 - 684}}}}{{{\\rm{760}}}}{\\rm{ = 0}}{\\rm{.1}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22371,'chemistry',59,370,689,'Which among the following solutions is not used in determination of the cell constant?','[{"text": "${\\\\rm{1}}{{\\\\rm{0}}^{{\\\\rm{ - 2}}}}{\\\\rm{MKCl}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{{\\\\rm{0}}^{{\\\\rm{ - 1}}}}{\\\\rm{MKCl}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}\\\\,\\\\,{\\\\rm{M}}\\\\,\\\\,{\\\\rm{KCl}}$", "isCorrect": false}, {"text": "${\\\\rm{Saturated}}\\\\,\\\\,{\\\\rm{KCl}}$", "isCorrect": true}]',3,'During the determination of cell constant, only standard solution of KCl is taken, Here options (1) , (2)  and (3) are standard solutions while (4), i.e., saturated KCl is not a standard solution, hence it is not used in cell constant determination.',NULL,'Medium','MCQ',2015,'MHTCET','2026-07-25 18:34:34.081508',NULL),
(22373,'chemistry',55,1240,3015,'Anthracene is a resonance hybrid of four resonating structures. The double bond character of ${\\mathrm{\\left(\\mathrm{C}^{1}-\\mathrm{C}^{2}\\right)}}$ is ____ .','[{"text": "0.25", "isCorrect": false}, {"text": "0.5", "isCorrect": false}, {"text": "0.75", "isCorrect": true}, {"text": "1", "isCorrect": false}]',2,'Anthracene show 4 resonating structures as:  <img src=\'/img/data/chemistry/55_22373_explanation_1.png\' alt=\'Question Image\' style=\'max-width:100%;\' />   Double bond character<br>No. of times double bond appears${\\mathrm{=\\dfrac{\\text { in all resonating structures }}{\\text { Total number of resonating structures }}}}$<br>${\\mathrm{=\\dfrac{3}{4}=0.75}}$',NULL,'Hard','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22374,'chemistry',58,170,374,'An aqueous solution containing 28% by mass of a liquid A (MW = 140) has a vapour pressure of 160 mm at ${\\rm{37^\\circ C}}$. The vapour pressure of the pure liquid A is (The vapour pressure of water at ${\\rm{37^\\circ C}}$ is 150 mm)','[{"text": "360 mm of Hg", "isCorrect": true}, {"text": "300 mm of Hg", "isCorrect": false}, {"text": "250 mm of Hg", "isCorrect": false}, {"text": "400 mm of Hg", "isCorrect": false}]',0,'Mass of liquid A = 28 g<br>Mass of water = 72 g<br>Number of moles of ${\\rm{A = }}\\frac{{{\\rm{28}}}}{{{\\rm{140}}}}{\\rm{ = 0}}{\\rm{.2}}$<br>Number of moles of water ${\\rm{ = }}\\frac{{{\\rm{72}}}}{{{\\rm{18}}}}{\\rm{ = 4}}$<br>According to Raoult’s law,<br>${{\\rm{P}}_{\\rm{T}}}{\\rm{ = P}}_{\\rm{A}}^{\\rm{0}}{{\\rm{X}}_{\\rm{A}}}{\\rm{ + P}}_{{{\\rm{H}}_{\\rm{2}}}{\\rm{O}}}^{\\rm{0}}{{\\rm{X}}_{{{\\rm{H}}_{\\rm{2}}}{\\rm{O}}}}$<br>${\\rm{184 = P}}_{\\rm{A}}^{\\rm{0}}\\left[ {\\frac{{{\\rm{0}}{\\rm{.2}}}}{{{\\rm{4}}{\\rm{.2}}}}} \\right]{\\rm{ + }}\\left( {{\\rm{150}}} \\right)\\left[ {\\frac{{\\rm{4}}}{{{\\rm{4}}{\\rm{.2}}}}} \\right]$<br>${\\rm{P}}_{\\rm{A}}^{\\rm{0}}{\\rm{ = 360}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{mm}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{Hg}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22375,'chemistry',59,370,690,'At a particular temperature, the ratio of molar conductance to specific conductance of 0.01 M NaCl solution is','[{"text": "${\\\\rm{1}}{{\\\\rm{0}}^{\\\\rm{3}}}{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{3}}}\\\\,\\\\,{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{{\\\\rm{0}}^{\\\\rm{3}}}{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{3}}}\\\\,\\\\,{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{10}}\\\\,\\\\,{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{3}}}\\\\,\\\\,{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{{\\\\rm{0}}^{\\\\rm{5}}}{\\\\rm{c}}{{\\\\rm{m}}^{\\\\rm{3}}}\\\\,\\\\,{\\\\rm{mo}}{{\\\\rm{l}}^{{\\\\rm{ - 1}}}}$", "isCorrect": true}]',3,'${{\\rm{\\Lambda }}_{\\rm{m}}}\\,\\,\\left( {{\\rm{molar}}\\,\\,{\\rm{conductance}}} \\right){\\rm{ = }}\\frac{{{\\rm{\\kappa  \\times 1000}}}}{{\\rm{M}}}$<br>$\\frac{{{{\\rm{\\Lambda }}_{\\rm{m}}}\\left( {{\\rm{oh}}{{\\rm{m}}^{{\\rm{ - 1}}}}{\\rm{c}}{{\\rm{m}}^{\\rm{2}}}{\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}} \\right)}}{{{\\rm{\\kappa }}\\left( {{\\rm{oh}}{{\\rm{m}}^{{\\rm{ - 1}}}}{\\rm{c}}{{\\rm{m}}^{{\\rm{ - 1}}}}} \\right)}}{\\rm{ = }}\\frac{{{\\rm{1000}}}}{{\\rm{M}}}{\\rm{ = }}\\frac{{{\\rm{1000}}}}{{{\\rm{0}}{\\rm{.01}}}}{\\rm{c}}{{\\rm{m}}^{\\rm{3}}}{\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}$<br>${\\rm{ = 1}}{{\\rm{0}}^{\\rm{5}}}{\\rm{c}}{{\\rm{m}}^{\\rm{3}}}\\,\\,{\\rm{mo}}{{\\rm{l}}^{{\\rm{ - 1}}}}$',NULL,'Easy','MCQ',2015,'KCET','2026-07-25 18:34:34.081508',NULL),
