(22460,'chemistry',58,168,364,'10 g of NaCl is dissolved in ${\\rm{1}}{{\\rm{0}}^{\\rm{6}}}{\\rm{g}}$ of the solution. Its concentration is:','[{"text": "100 ppm", "isCorrect": false}, {"text": "0.1 ppm", "isCorrect": false}, {"text": "1 ppm", "isCorrect": false}, {"text": "10 ppm", "isCorrect": true}]',3,'${\\rm{ppm = }}\\frac{{{\\rm{Mass}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{solute}}}}{{{\\rm{Mass}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{of}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{solution}}}}{\\rm{ \\times 1}}{{\\rm{0}}^{\\rm{6}}}$<br>$\\therefore {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\rm{ppm = }}\\frac{{{\\rm{10}}}}{{{\\rm{1}}{{\\rm{0}}^{\\rm{6}}}}}{\\rm{ \\times 1}}{{\\rm{0}}^{\\rm{6}}}{\\rm{ = 10}}{\\mkern 1mu} {\\mkern 1mu} {\\rm{ppm}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(22461,'chemistry',59,368,682,'The equilibrium constant of the reaction:<br>${{\\text{A}}_{{\\text{(s)}}}}{\\text{ + 2B}}_{{\\text{(aq)}}}^{\\text{ + }} \\rightleftharpoons {\\text{A}}_{{\\text{(aq)}}}^{{\\text{2 + }}}{\\text{2}}{{\\text{B}}_{{\\text{(s)}}}}{\\text{;}}\\,\\,{\\text{E}}_{{\\text{cell}}}^{\\text{o}}{\\text{ = 0}}{\\text{.0295}}\\,\\,{\\text{V}}$<br>${\\rm{is}}\\,\\,\\left[ {\\frac{{{\\rm{2}}{\\rm{.303}}\\,\\,{\\rm{RT}}}}{{\\rm{F}}}{\\rm{ = 0}}{\\rm{.059}}} \\right]$','[{"text": "${\\\\rm{10}}$", "isCorrect": true}, {"text": "${\\\\rm{2 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{2}}}$", "isCorrect": false}, {"text": "${\\\\rm{3 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{2}}}$", "isCorrect": false}, {"text": "${\\\\rm{2 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{5}}}$", "isCorrect": false}]',0,'${\\rm{E}}_{{\\rm{cell}}}^{\\rm{o}}{\\rm{ = }}\\frac{{{\\rm{0}}{\\rm{.0591}}}}{{\\rm{n}}}{\\rm{lo}}{{\\rm{g}}_{{\\rm{10}}}}{\\rm{K}}$<br>${\\rm{N = 2,E}}_{{\\rm{cell}}}^{\\rm{o}}{\\rm{ = 0}}{\\rm{.0295 V}}$<br>${\\rm{0}}{\\rm{.0295 = }}\\frac{{{\\rm{0}}{\\rm{.0591}}}}{{\\rm{2}}}{\\rm{lo}}{{\\rm{g}}_{{\\rm{10}}}}{\\rm{K}}$<br>${\\rm{K = anti}}\\,\\,{\\rm{log}}\\,\\,{\\rm{0}}{\\rm{.998 = 9}}{\\rm{.96}} \\approx {\\rm{10}}$.',NULL,'Easy','MCQ',2012,'KCET','2026-07-25 18:34:34.081508',NULL),
