(23308,'chemistry',59,368,682,'The standard emf of a primary battery having one electrode change is found to be 0.591 V at ${\\rm{25^\\circ C}}$. The equilibrium constant of the reaction is:','[{"text": "${\\\\rm{1}}{\\\\rm{.0 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{1}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{\\\\rm{.0 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{10}}}}$", "isCorrect": true}, {"text": "${\\\\rm{1}}{\\\\rm{.0 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{30}}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{\\\\rm{.0 \\\\times 1}}{{\\\\rm{0}}^{\\\\rm{5}}}$", "isCorrect": false}]',1,'${\\rm{E}}_{{\\rm{cell}}}^{\\rm{o}}\\,\\,{\\rm{ = }}\\,\\,\\frac{{{\\rm{0}}{\\rm{.059}}}}{{\\rm{1}}}\\,\\,{\\rm{log}}\\,\\,{{\\rm{K}}_{\\rm{c}}}$<br>${\\rm{0}}{\\rm{.591}}\\,\\,{\\rm{ = }}\\,\\,\\frac{{{\\rm{0}}{\\rm{.059}}}}{{\\rm{1}}}\\,\\,{\\rm{log}}\\,\\,{{\\rm{K}}_{\\rm{c}}}$<br>$\\therefore \\,\\,{{\\rm{K}}_{\\rm{c}}}\\,\\,{\\rm{ = }}\\,\\,{\\rm{1 \\times 1}}{{\\rm{0}}^{{\\rm{10}}}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
