(23395,'chemistry',58,168,366,'The molarity of a solution containing $5.0 \\mathrm{~g}$ of $\\mathrm{NaOH}$ in $250 \\mathrm{~mL}$ solution is','[{"text": "$0.1 \\\\mathrm{M}$", "isCorrect": false}, {"text": "$0.5 \\\\mathrm{M}$", "isCorrect": true}, {"text": "$1.0 \\\\mathrm{M}$", "isCorrect": false}, {"text": "$2.0 \\\\mathrm{M}$", "isCorrect": false}]',1,'Molarity<br>$ = \\frac{{{\\rm{number}}\\,{\\rm{of}}\\,{\\rm{moles}}\\,{\\rm{of}}\\,{\\rm{solute}}}}{{{\\rm{volume}}\\,{\\rm{of}}\\,{\\rm{solution}}}}$<br>$ = \\frac{{5 \\times 1000}}{{40 \\times 250}} = 0.5{\\rm{M}}$<br>$\\left[\\because \\text { Moles of } \\mathrm{NaOH}=\\dfrac{5}{40}\\right]$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(23396,'chemistry',59,368,681,'Which of the following statements is correct?','[{"text": "${\\\\rm{E}}_{{\\\\rm{cell}}}^{\\\\rm{o}}\\\\,\\\\,{\\\\rm{and}}\\\\,\\\\,{{\\\\rm{\\\\Delta }}_{\\\\rm{r}}}{\\\\rm{G}}$ of cell reaction both are extensive properties.", "isCorrect": false}, {"text": "${\\\\rm{E}}_{{\\\\rm{cell}}}^{\\\\rm{o}}\\\\,\\\\,{\\\\rm{and}}\\\\,\\\\,{{\\\\rm{\\\\Delta }}_{\\\\rm{r}}}{\\\\rm{G}}$ of cell reaction both are intensive properties.", "isCorrect": false}, {"text": "${\\\\rm{E}}_{{\\\\rm{cell}}}^{\\\\rm{o}}$  is an intensive property while ${{\\\\rm{\\\\Delta }}_{\\\\rm{r}}}{\\\\rm{G}}$ of cell reaction is an extensive property.", "isCorrect": true}, {"text": "${\\\\rm{E}}_{{\\\\rm{cell}}}^{\\\\rm{o}}$ is an extensive property while ${{\\\\rm{\\\\Delta }}_{\\\\rm{r}}}{\\\\rm{G}}$ cell reaction is an intensive property.", "isCorrect": false}]',2,'Standard EMF of cell depends on the nature of the electrode but not on the amount of substance so, it is an intensive property. Standard free energy of the reaction depends on the amount of the substance so, it is an extensive property.',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
