(23452,'chemistry',59,372,694,'Molar conductivity of ${\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{OH}}$ can be calculated by the equation,','[{"text": "${\\\\rm{\\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{OH}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ = \\\\Lambda }}_{{\\\\rm{Ba}}{{\\\\left( {{\\\\rm{OH}}} \\\\right)}_{\\\\rm{2}}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ + \\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ - \\\\Lambda }}_{{\\\\rm{BaC}}{{\\\\rm{l}}_{\\\\rm{2}}}}^{\\\\rm{^\\\\circ }}$", "isCorrect": false}, {"text": "${\\\\rm{\\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{OH}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ = }}\\\\frac{{{\\\\rm{\\\\Lambda }}_{{\\\\rm{Ba}}{{\\\\left( {{\\\\rm{OH}}} \\\\right)}_{\\\\rm{2}}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ + 2\\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ - \\\\Lambda }}_{{\\\\rm{BaC}}{{\\\\rm{l}}_{\\\\rm{2}}}}^{\\\\rm{^\\\\circ }}}}{{\\\\rm{2}}}$", "isCorrect": true}, {"text": "${\\\\rm{\\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{OH}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ = \\\\Lambda }}_{{\\\\rm{BaC}}{{\\\\rm{l}}_{\\\\rm{2}}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ + 2\\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ - \\\\Lambda }}_{{\\\\rm{Ba}}{{\\\\left( {{\\\\rm{OH}}} \\\\right)}_{\\\\rm{2}}}}^{\\\\rm{^\\\\circ }}$", "isCorrect": false}, {"text": "${\\\\rm{\\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{OH}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ = }}\\\\frac{{{\\\\rm{2\\\\Lambda }}_{{\\\\rm{N}}{{\\\\rm{H}}_{\\\\rm{4}}}{\\\\rm{Cl}}}^{\\\\rm{^\\\\circ }}{\\\\rm{ + \\\\Lambda }}_{{\\\\rm{Ba}}{{\\\\left( {{\\\\rm{OH}}} \\\\right)}_{\\\\rm{2}}}}^{\\\\rm{^\\\\circ }}}}{{\\\\rm{2}}}$", "isCorrect": false}]',1,'${\\rm{\\Lambda }}_{{\\rm{Ba}}{{\\left( {{\\rm{OH}}} \\right)}_{\\rm{2}}}}^{\\rm{^\\circ }}{\\rm{ = \\lambda }}_{{\\rm{B}}{{\\rm{a}}^{{\\rm{ + 2}}}}}^{\\rm{^\\circ }}{\\rm{ + 2\\lambda }}_{{\\rm{O}}{{\\rm{H}}^{{\\rm{ - 1}}}}}^{\\rm{^\\circ }} \\to \\left( {\\rm{1}} \\right)$<br>${\\rm{\\Lambda }}_{{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}}}^{\\rm{^\\circ }}{\\rm{ = \\lambda }}_{{\\rm{N}}{{\\rm{H}}_{{{\\rm{4}}^{\\rm{ + }}}}}}^{\\rm{^\\circ }}{\\rm{ + 2\\lambda }}_{{\\rm{C}}{{\\rm{l}}^{{\\rm{ - 1}}}}}^{\\rm{^\\circ }} \\to \\left( {\\rm{2}} \\right)$<br>${\\rm{\\Lambda }}_{{\\rm{BaC}}{{\\rm{l}}_{\\rm{2}}}}^{\\rm{^\\circ }}{\\rm{ = \\lambda }}_{{\\rm{B}}{{\\rm{a}}^{{\\rm{ + 2}}}}}^{\\rm{^\\circ }}{\\rm{ + 2\\lambda }}_{{\\rm{C}}{{\\rm{l}}^{\\rm{ - }}}}^{\\rm{^\\circ }} \\to \\left( {\\rm{3}} \\right)$<br>According to Kohlrausch’s law, from (1), (2), (3)<br>${\\rm{2\\Lambda }}_{{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{OH}}}^{\\rm{^\\circ }}{\\rm{ = \\Lambda }}_{{\\rm{Ba}}{{\\left( {{\\rm{OH}}} \\right)}_{\\rm{2}}}}^{\\rm{^\\circ }}{\\rm{ + 2\\Lambda }}_{{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}}}^{\\rm{^\\circ }}{\\rm{ - \\Lambda }}_{{\\rm{BaC}}{{\\rm{l}}_{\\rm{2}}}}^{\\rm{^\\circ }}$<br>${\\rm{\\Lambda }}_{{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{OH}}}^{\\rm{^\\circ }}{\\rm{ = }}\\frac{{{\\rm{\\Lambda }}_{{\\rm{Ba}}{{\\left( {{\\rm{OH}}} \\right)}_{\\rm{2}}}}^{\\rm{^\\circ }}{\\rm{ + 2\\Lambda }}_{{\\rm{N}}{{\\rm{H}}_{\\rm{4}}}{\\rm{Cl}}}^{\\rm{^\\circ }}{\\rm{ - \\Lambda }}_{{\\rm{BaC}}{{\\rm{l}}_{\\rm{2}}}}^{\\rm{^\\circ }}}}{{\\rm{2}}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
