(23454,'chemistry',58,176,385,'The molal elevation constant of water is $0.52^{\\circ} \\mathrm{cm}^{-1}$. The boiling point of 1.0 molal aqueous $\\mathrm{KCl}$ solution (assuming complete dissociation of $\\mathrm{KCl}$ ), therefore, should be','[{"text": "$98.96^{\\\\circ} \\\\mathrm{C}$", "isCorrect": false}, {"text": "$100.52^{\\\\circ} \\\\mathrm{C}$", "isCorrect": false}, {"text": "$101.04^{\\\\circ} \\\\mathrm{C}$", "isCorrect": true}, {"text": "$107.01^{\\\\circ} \\\\mathrm{C}$", "isCorrect": false}]',2,'Total number of ions <br>${\\rm{KCl}} \\to {{\\rm{K}}^ + } + {\\rm{C}}{{\\rm{l}}^ - }$<br>$\\therefore \\quad {\\rm{i}} = 2$<br>${\\rm{\\Delta }}{{\\rm{T}}_{\\rm{b}}} = {\\rm{im}}{{\\rm{K}}_{\\rm{b}}}$<br>$ = 2 \\times 1 \\times 0.52 = 1.04$<br>$\\therefore {{\\rm{T}}_{\\rm{b}}} = {\\rm{T}}_{\\rm{b}}^{\\rm{0}} + {\\rm{\\Delta }}{{\\rm{T}}_{\\rm{b}}} = 100 + 1.04$<br>$ = 101.04^\\circ {\\rm{C}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
