(23565,'chemistry',59,370,690,'What is the molar conductivity of $0.05\\,\\,{\\text{M}}$ solution of sodium hydroxide, if its conductivity is $0.0118\\,\\,{\\text{S c}}{{\\text{m}}^{ - 1}}$ at $298 \\mathrm{~K}$ ?','[{"text": "$236\\\\,\\\\,{\\\\text{S}}\\\\,\\\\,{\\\\text{c}}{{\\\\text{m}}^2} {\\\\text{mo}}{{\\\\text{l}}^{ - 1}}$", "isCorrect": true}, {"text": "$423\\\\,\\\\,{\\\\text{S c}}{{\\\\text{m}}^2} {\\\\text{mo}}{{\\\\text{l}}^{ - 1}}$", "isCorrect": false}, {"text": "$354\\\\,\\\\,{\\\\text{S c}}{{\\\\text{m}}^2} {\\\\text{mo}}{{\\\\text{l}}^{ - 1}}$", "isCorrect": false}, {"text": "$590\\\\,\\\\,{\\\\text{S c}}{{\\\\text{m}}^2}\\\\,{\\\\text{mo}}{{\\\\text{l}}^{ - 1}}$", "isCorrect": false}]',0,'$\\mathrm{c}=0.05 \\mathrm{M}, \\mathrm{k}=0.0118 \\mathrm{Scm}^{-1}$<br>$\\wedge=\\dfrac{1000 \\mathrm{k}}{\\mathrm{c}}$<br>$ = \\frac{{1000{{\\text{c}}^3}\\,{{\\text{L}}^{ - 1}} \\times 0.0118\\,\\,{\\text{S c}}{{\\text{m}}^{ - 1}}}}{{0.05{\\text{mol }}{{\\text{L}}^{ - 1}}}}$<br>$ = 236\\,\\,{\\text{S c}}{{\\text{m}}^2}\\,{\\text{mo}}{{\\text{l}}^{ - 1}}$',NULL,'Easy','MCQ',2021,'MHTCET','2026-07-25 18:34:34.081508',NULL),
(23566,'chemistry',60,585,1176,'The rate of reaction between two reactants A and B decreases by a factor 4 if the concentration of reactant B is doubled. The order of the reaction with respect to B is','[{"text": "${\\\\rm{ - 1}}$", "isCorrect": false}, {"text": "${\\\\rm{ - 2}}$", "isCorrect": true}, {"text": "2", "isCorrect": false}, {"text": "1", "isCorrect": false}]',1,'$\\mathrm{r}=\\mathrm{k}[\\mathrm{A}]^{\\mathrm{n}}[\\mathrm{B}]^{\\mathrm{m}}$<br>$\\begin{aligned}& \\dfrac{r}{4}=\\mathrm{k}[\\mathrm{A}]^{\\mathrm{n}}[2 \\mathrm{~B}]^{\\mathrm{m}} \\\\& \\dfrac{1}{4}=2^{m} \\\\& m=-2\\end{aligned}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(23569,'chemistry',59,373,697,'How many faraday of electricity is required to produce $10 \\mathrm{~g}$ of calcium metal  $\\left( {{\\text{molar}}\\,\\,{\\text{mass}} = 40 {\\text{g}}\\,{\\text{mo}}{{\\text{l}}^{ - 1}}} \\right)$ from calcium ions?','[{"text": "$1.5 \\\\mathrm{~F}$", "isCorrect": false}, {"text": "$2.0 \\\\mathrm{~F}$", "isCorrect": false}, {"text": "$0.50 \\\\mathrm{~F}$", "isCorrect": true}, {"text": "$1.0 \\\\mathrm{~F}$", "isCorrect": false}]',2,'$\\mathrm{Ca}_{(\\text {aq) }}^{2+}+2 \\mathrm{e}^{-} \\rightarrow \\mathrm{Ca}_{(\\mathrm{s})}$<br>$\\therefore 40 \\mathrm{~g}$ of Ca requires $2 \\mathrm{~F}$ of electricity<br>$\\therefore 10 \\mathrm{~g}$ of $\\mathrm{Ca}=\\dfrac{2 \\times 10}{40}=0.5 \\mathrm{~F}$ of electricity',NULL,'Easy','MCQ',2021,'MHTCET','2026-07-25 18:34:34.081508',NULL),
