(23719,'chemistry',59,370,689,'The specific conductivity of  ${\\text{N}}/10\\,\\,{\\text{KCl}}$ solution at $20^{\\circ} \\mathrm{C}$ is $0.0212 \\Omega^{-1} \\mathrm{~cm}^{-1}$ and the resistance of the cell containing this solution at $20^{\\circ} \\mathrm{C}$ is $55 \\Omega$. The cell constant is:','[{"text": "$3.324 \\\\mathrm{~cm}^{-1}$", "isCorrect": false}, {"text": "$1.166 \\\\mathrm{~cm}^{-1}$", "isCorrect": true}, {"text": "$2.372 \\\\mathrm{~cm}^{-1}$", "isCorrect": false}, {"text": "$3.682 \\\\mathrm{~cm}^{-1}$", "isCorrect": false}]',1,'$\\kappa {\\text{ }} = $ Conductance $ \\times \\frac{{\\text{l}}}{{{\\text{ A}}}}$<br>$\\frac{{\\text{l}}}{{{\\text{ A}}}} = \\kappa  \\times \\frac{{\\text{1}}}{{{\\text{ Conductance }}}}{\\text{ =  K}} \\times {\\text{R}}$<br>$=0.0212 \\times 55=1.166 \\mathrm{~cm}^{-1}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(23723,'chemistry',59,371,693,'$\\mathrm{NaCl}, \\mathrm{MgCl}_{2}$ and $\\mathrm{CaSO}_{4}$ are known as:','[{"text": "1-1,2-1,2-2 type of electrolytes respectively.", "isCorrect": true}, {"text": "Strong, weak and strong electrolytes respectively.", "isCorrect": false}, {"text": "Electrolytes with different value of A.", "isCorrect": false}, {"text": "Electrolytes with same molar conductivity.", "isCorrect": false}]',0,'Depending on the charges on the cation and anion produced in the dissociation of the electrolyte in solution, the type of electrolytes are known as $1-1,2-1$ and $2-2$ electrolytes respectively.<br>$\\mathrm{NaCl} \\rightarrow \\mathrm{Na}^{+}+\\mathrm{Cl}^{-}(1-1)$<br>$\\mathrm{MgCl}_{2} \\rightarrow \\mathrm{Mg}^{2+}+2 \\mathrm{Cl}^{-}(2-1)$<br>$\\mathrm{CaSO}_{4} \\rightarrow \\mathrm{Ca}^{2+}+\\mathrm{SO}_{4}^{2-}(2-2)$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
