(24357,'chemistry',63,807,1744,'On heating a mixture of $\\mathrm{NH}_{4} \\mathrm{Cl}$ and $\\mathrm{KNO}_{2}$ we get','[{"text": "$\\\\mathrm{NH}_{4} \\\\mathrm{NO}_{3}$", "isCorrect": false}, {"text": "${{\\\\rm{N}}_{\\\\rm{2}}}$", "isCorrect": true}, {"text": "$\\\\mathrm{NO}$", "isCorrect": false}, {"text": "$\\\\mathrm{N}_{2} \\\\mathrm{O}$", "isCorrect": false}]',1,'$\\mathrm{NH}_{4} \\mathrm{Cl}+\\mathrm{KNO}_{2} \\stackrel{\\Delta}{\\longrightarrow} \\mathrm{NH}_{4} \\mathrm{NO}_{2}+\\mathrm{KCl}$<br>$\\mathrm{NH}_{4} \\mathrm{NO}_{2} \\stackrel{\\Delta}{\\longrightarrow} \\mathrm{N}_{2}+2 \\mathrm{H}_{2} \\mathrm{O}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
