(24402,'chemistry',60,589,1186,'Which one of the following does not represent Arrhenius equation?','[{"text": "${\\\\mathrm{\\\\log \\\\mathrm{k}=\\\\log \\\\mathrm{A}-\\\\dfrac{\\\\mathrm{Ea}}{2.303 \\\\mathrm{RT}}}}$", "isCorrect": false}, {"text": "${\\\\mathrm{\\\\mathrm{k}=\\\\mathrm{Ae}^{-\\\\mathrm{Ea} / \\\\mathrm{RT}}}}$", "isCorrect": false}, {"text": "$\\\\ln \\\\,k\\\\,{\\\\rm{ = }} - \\\\frac{{{\\\\rm{Ea}}}}{{{\\\\rm{RT}}}}{\\\\rm{ + ln}}\\\\,{\\\\rm{A}}$", "isCorrect": false}, {"text": "${\\\\rm{k = A}}{{\\\\rm{e}}^{{\\\\rm{Ea/RT}}}}$", "isCorrect": true}]',3,'${\\mathrm{\\mathrm{K}=\\mathrm{Ae}^{-\\mathrm{Ea} / \\mathrm{RT}}}}$ but not<br>${\\rm{K}}\\,{\\rm{ = }}\\,{\\rm{A}}{{\\rm{e}}^{{\\rm{Ea/RT}}}}$',NULL,'Easy','MCQ',2024,'KCET','2026-07-25 18:34:34.081508',NULL),
