(24802,'chemistry',64,192,1923,'Which of the following are amphoteric oxides? $\\mathrm{\\mathrm{Mn}_{2} \\mathrm{O}_{7}, \\mathrm{CrO}_{3}, \\mathrm{Cr}_{2} \\mathrm{O}_{3}, \\mathrm{CrO}, \\mathrm{V}_{2} \\mathrm{O}_{5}, \\mathrm{~V}_{2} \\mathrm{O}_{4}}$','[{"text": "$\\\\mathrm{\\\\mathrm{V}_{2} \\\\mathrm{O}_{5}, \\\\mathrm{Cr}_{2} \\\\mathrm{O}_{3}}$", "isCorrect": true}, {"text": "$\\\\mathrm{\\\\mathrm{Mn}_{2} \\\\mathrm{O}_{7}, \\\\mathrm{CrO}_{3}}$", "isCorrect": false}, {"text": "$\\\\mathrm{\\\\mathrm{CrO}, \\\\mathrm{V}_{2} \\\\mathrm{O}_{5}}$", "isCorrect": false}, {"text": "$\\\\mathrm{\\\\mathrm{V}_{2} \\\\mathrm{O}_{5}, \\\\mathrm{~V}_{2} \\\\mathrm{O}_{4}}$", "isCorrect": false}]',0,NULL,NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
