(25255,'chemistry',65,959,2237,'Which of the following complex ion is not expected to absorb visible light?','[{"text": "$\\\\left[\\\\mathrm{Ni}(\\\\mathrm{CN})_{4}\\\\right]^{2-}$", "isCorrect": true}, {"text": "$\\\\left[\\\\mathrm{Cr}\\\\left(\\\\mathrm{NH}_{3}\\\\right)_{6}\\\\right]^{3+}$", "isCorrect": false}, {"text": "$\\\\left[\\\\mathrm{Fe}\\\\left(\\\\mathrm{H}_{2} \\\\mathrm{O}\\\\right)_{6}\\\\right]^{2+}$", "isCorrect": false}, {"text": "$\\\\left[\\\\mathrm{Ni}\\\\left(\\\\mathrm{H}_{2} \\\\mathrm{O}\\\\right)_{6}\\\\right]^{2+}$", "isCorrect": false}]',0,'$\\left[\\mathrm{Ni}(\\mathrm{CN})_{4}\\right]^{2-}:$ Number of unpaired electrons $=0$<br>$\\left[\\mathrm{Cr}\\left(\\mathrm{NH}_{3}\\right)_{6}\\right]^{3+}:$ Number of unpaired electrons $=3$<br>$\\left[\\mathrm{Fe}\\left(\\mathrm{H}_{2} \\mathrm{O}\\right)_{6}\\right]^{2+}:$ Number of unpaired electrons $=4$<br>$\\left[\\mathrm{Ni}\\left(\\mathrm{H}_{2} \\mathrm{O}\\right)_{6}\\right]^{2+}:$ Number of unpaired electrons $=2$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
