(25323,'chemistry',65,960,2240,'In which of the following coordinate compounds the central metal atom obeys the EAN rule?','[{"text": "$\\\\mathrm{K}_{3}\\\\left[\\\\mathrm{Fe}(\\\\mathrm{CN})_{6}\\\\right]$", "isCorrect": false}, {"text": "$\\\\mathrm{K}_{4}\\\\left[\\\\mathrm{Fe}(\\\\mathrm{CN})_{6}\\\\right]$", "isCorrect": true}, {"text": "$\\\\left[\\\\mathrm{Cu}\\\\left(\\\\mathrm{NH}_{3}\\\\right)_{4}\\\\right] \\\\mathrm{SO}_{4}$", "isCorrect": false}, {"text": "All the above", "isCorrect": false}]',1,'$\\mathrm{K}_{4}\\left[\\mathrm{Fe}(\\mathrm{CN})_{6}\\right]$ obeys the EAN rule.<br>${\\text{EAN = 26 - 2 + 2}} \\times {\\text{6 = 36}}$',NULL,'Hard','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
