(25396,'chemistry',65,954,2217,'In the coordination compound, $\\mathrm{K}_{4}\\left[\\mathrm{Ni}(\\mathrm{CN})_{4}\\right]$, oxidation state of nickel is','[{"text": "-1", "isCorrect": false}, {"text": "0", "isCorrect": true}, {"text": "+1", "isCorrect": false}, {"text": "+2", "isCorrect": false}]',1,'${\\text{ + 1}} \\times {\\text{4 + x - 1}} \\times {\\text{4 = 0}}$<br>${\\text{4  +  x  -  4  =  0}} \\Rightarrow {\\text{x  =  0 for Ni}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(25398,'chemistry',63,808,1761,'Which of the following statement is incorrect','[{"text": "hypophosphorous acid reduces silver nitrate to silver", "isCorrect": false}, {"text": "in solid state $\\\\mathrm{PCl}_{5}$ exists as<br>$\\\\left[\\\\mathrm{PCl}_{4}\\\\right]^{+}\\\\left[\\\\mathrm{PCl}_{6}\\\\right]^{-}$", "isCorrect": false}, {"text": "pure phosphine is non-inflammable", "isCorrect": false}, {"text": "phosphorous acid on heating disproportionates to give metal phosphoric acid and phosphine", "isCorrect": true}]',3,'$\\underset{\\substack{\\text { Phosphorous } \\\\ \\text { acid }}}{4 \\mathrm{H}_{3} \\mathrm{PO}_{3}} \\stackrel{200^{\\circ} \\mathrm{C}}{\\longrightarrow} \\underset{\\substack{\\text { Orthophosphoric } \\\\ \\text { acid }}}{3 \\mathrm{H}_{3} \\mathrm{PO}_{4}}+\\underset{\\text { Phosphine }}{\\mathrm{PH}_{3}}$',NULL,'Medium','MCQ',2014,'KCET','2026-07-25 18:34:34.081508',NULL),
