(25402,'chemistry',63,813,1776,'Which of the following does not give oxygen on heating?','[{"text": "$\\\\mathrm{Zn}\\\\left(\\\\mathrm{ClO}_{3}\\\\right)_{2}$", "isCorrect": false}, {"text": "$\\\\mathrm{KClO}_{3}$", "isCorrect": false}, {"text": "$\\\\left(\\\\mathrm{NH}_{4}\\\\right)_{2} \\\\mathrm{Cr}_{2} \\\\mathrm{O}_{7}$", "isCorrect": true}, {"text": "$\\\\mathrm{K}_{2} \\\\mathrm{Cr}_{2} \\\\mathrm{O}_{7}$", "isCorrect": false}]',2,'$\\left(\\mathrm{NH}_{4}\\right)_{2} \\mathrm{Cr}_{2} \\mathrm{O}_{7} \\stackrel{\\Delta}{\\longrightarrow} \\mathrm{N}_{2}+\\mathrm{Cr}_{2} \\mathrm{O}_{3}+4 \\mathrm{H}_{2} \\mathrm{O}$;<br>rest all gives oxygen.',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
