(25558,'chemistry',64,192,1925,'Name the gas that can readily decolourise acidified $\\mathrm{\\mathrm{KMnO}_{4}}$ solution:','[{"text": "$\\\\mathrm{\\\\mathrm{SO}_{2}}$", "isCorrect": true}, {"text": "$\\\\mathrm{\\\\mathrm{NO}_{2}}$", "isCorrect": false}, {"text": "$\\\\mathrm{\\\\mathrm{P}_{2} \\\\mathrm{O}_{5}}$", "isCorrect": false}, {"text": "$\\\\mathrm{\\\\mathrm{CO}_{2}}$", "isCorrect": false}]',0,'$\\mathop {{\\rm{KMn}}{{\\rm{O}}_{\\rm{4}}}}\\limits^{{\\rm{ + 7}}} {\\rm{ + }}\\,\\,\\,\\mathop {{\\rm{S}}{{\\rm{O}}_{\\rm{2}}}}\\limits^{{\\rm{ + 4}}} \\,\\,\\,\\, \\to \\,\\,\\,{\\rm{MnS}}{{\\rm{O}}_{\\rm{4}}}{\\rm{ + }}{{\\rm{H}}_{\\rm{2}}}{\\rm{S}}{{\\rm{O}}_{\\rm{4}}}{\\rm{ + }}{{\\rm{K}}_{\\rm{2}}}{\\rm{S}}{{\\rm{O}}_{\\rm{4}}}$<br>$\\,\\left( {{\\rm{O}}{\\rm{.A}}} \\right)\\,\\,\\,\\,\\,\\,\\,\\left( {{\\rm{R}}{\\rm{.A}}} \\right)\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\left( {{\\rm{colourless}}} \\right)$',NULL,'Medium','MCQ',2017,'NEET','2026-07-25 18:34:34.081508',NULL),
(25559,'chemistry',63,818,1812,'Yellow colour of chlorine water fades because of','[{"text": "Form action of $\\\\mathrm{HCl}$ and $\\\\mathrm{HOCl}$", "isCorrect": true}, {"text": "Chlorine gas escapes", "isCorrect": false}, {"text": "$\\\\mathrm{ClO}_{2}+\\\\mathrm{H}_{2}$", "isCorrect": false}, {"text": "$\\\\mathrm{Cl}_{2} \\\\mathrm{O}$<br>", "isCorrect": false}]',0,'Chlorine water on standing loses yellow colour due to formation of $\\mathrm{HCl}$ and $\\mathrm{HOCl}$ which in turn provides nascent oxygen.<br>$\\begin{aligned}& \\mathrm{Cl}_{2}+\\mathrm{H}_{2} \\mathrm{O} \\rightarrow \\mathrm{HCl}+\\mathrm{HOCl} \\\\& \\mathrm{HClO} \\rightarrow \\mathrm{HCl}+\\underset{\\text { Nascent oxygen }}{[\\mathrm{O}]}\\end{aligned}$<br>',NULL,'Easy','MCQ',2019,'AIIMS','2026-07-25 18:34:34.081508',NULL),
