(26411,'chemistry',64,191,1918,'Which of the following is wrongly paired?','[{"text": "$\\\\mathrm{MnSO}_{4}$ :  Yellow", "isCorrect": true}, {"text": "$\\\\mathrm{Cr}_{2}\\\\left(\\\\mathrm{SO}_{4}\\\\right)_{3}:$ Green", "isCorrect": false}, {"text": "$\\\\mathrm{K}_{2} \\\\mathrm{Cr}_{2} \\\\mathrm{O}_{7}$ :  Orange", "isCorrect": false}, {"text": "$\\\\mathrm{CuSO}_{4} \\\\cdot 5 \\\\mathrm{H}_{2} \\\\mathrm{O}:$ Blue", "isCorrect": false}]',0,'$\\mathrm{Mn}^{+2} \\mathrm{SO}_{4}^{2-} \\rightarrow$ Colourless due to forbidden $\\mathrm{d}-\\mathrm{d}$ transition ( $\\mathrm{d}^{5}$ stability)',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(26413,'chemistry',63,819,1813,'Identify the statement which is not correct regarding $\\mathrm{CuSO}_{4}$.','[{"text": "It reacts with $\\\\mathrm{KI}$ to give iodine.", "isCorrect": false}, {"text": "It reacts with $\\\\mathrm{KCl}$ to give $\\\\mathrm{Cu}_{2} \\\\mathrm{Cl}_{2}$.", "isCorrect": true}, {"text": "It reacts with $\\\\mathrm{NaOH}$ and glucose to give $\\\\mathrm{Cu}_{2} \\\\mathrm{O}$.", "isCorrect": false}, {"text": "It gives $\\\\mathrm{CuO}$ on strong heating in air.", "isCorrect": false}]',1,'$\\mathrm{CuSO}_{4}$ reacts with $\\mathrm{KI}$ to give white precipitate of $\\mathrm{Cu}_{2} \\mathrm{I}_{2}$ and evolve $\\mathrm{I}_{2}$. But it does not react with $\\mathrm{KCl}$ in the same way.',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(26414,'chemistry',66,1038,2461,'A bromoalkane \' $\\mathrm{X}$ \' reacts with magnesium in dry ether to form compound \' $\\mathrm{Y}$ \'. The reaction of \' $\\mathrm{Y}$ \' with methanal followed by hydrolysis yield a straight chain alcohol having molecular formula, $\\mathrm{C}_{4} \\mathrm{H}_{10} \\mathrm{O}$. The compound \' $\\mathrm{X}$ \' is','[{"text": "Bromomethane", "isCorrect": false}, {"text": "Bromoethane", "isCorrect": false}, {"text": "1 - Bromopropane", "isCorrect": true}, {"text": "2 - Bromopropane", "isCorrect": false}]',2,'$\\mathop {{\\text{C}}{{\\text{H}}_{\\text{3}}}{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{Br}}}\\limits_{\\begin{array}{*{20}{c}}\n  {{\\text{1 - Bromopropane}}} \\\\ \n  {{\\text{(x)}}} \n\\end{array}} {\\text{ + Mg}}\\xrightarrow{{{\\text{Dry}}\\,\\,{\\text{ether}}}}{\\text{C}}{{\\text{H}}_{\\text{3}}}{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{MgBr}}$<br>$\\xrightarrow{{{\\text{HCHO}}}}{\\text{C}}{{\\text{H}}_{\\text{3}}}{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{C}}{{\\text{H}}_{\\text{2}}}{\\text{ - O - MgBr}}$  <img src=\'/img/data/chemistry/66_26414_explanation_1.png\' alt=\'Question Image\' style=\'max-width:100%;\' />',NULL,'Medium','MCQ',2018,'AIIMS','2026-07-25 18:34:34.081508',NULL),
(26429,'chemistry',65,960,2238,'Which complex compound is most stable?','[{"text": "$\\\\left[\\\\mathrm{Co}\\\\left(\\\\mathrm{NH}_{3}\\\\right)_{3}\\\\left(\\\\mathrm{NO}_{3}\\\\right)_{3}\\\\right]$", "isCorrect": false}, {"text": "$\\\\left[\\\\mathrm{CoCl}_{2}\\\\left(\\\\mathrm{en}_{2}\\\\right)\\\\right] \\\\mathrm{NO}_{3}$", "isCorrect": true}, {"text": "$\\\\left[\\\\mathrm{Co}\\\\left(\\\\mathrm{NH}_{3}\\\\right)_{6}\\\\right]_{2}\\\\left(\\\\mathrm{SO}_{4}\\\\right)_{3}$", "isCorrect": false}, {"text": "$\\\\left[\\\\mathrm{Co}\\\\left(\\\\mathrm{NH}_{3}\\\\right)_{4}\\\\left(\\\\mathrm{H}_{2} \\\\mathrm{O}\\\\right) \\\\mathrm{Br}\\\\right]\\\\left(\\\\mathrm{NO}_{3}\\\\right)_{2}$", "isCorrect": false}]',1,'Due to chelation effect of (en). As chelation increases, stability increases.',NULL,'Medium','MCQ',2023,'NEET','2026-07-25 18:34:34.081508',NULL),
(26415,'chemistry',64,192,1925,'Number of electrons transferred in each case when $\\mathrm{KMnO}_{4}$ acts as an oxidizing agent to give$\\mathrm{MnO}_{2}, \\mathrm{Mn}^{2+}, \\mathrm{Mn}(\\mathrm{OH})_{3}, \\mathrm{MnO}_{4}^{2-}$ are, respectively.','[{"text": "$3,5,4$, and 1", "isCorrect": true}, {"text": "$4,3,1$, and 5", "isCorrect": false}, {"text": "$1,3,4$, and 5", "isCorrect": false}, {"text": "$5,4,3$, and 1", "isCorrect": false}]',0,'$\\mathop {{\\text{KMn}}{{\\text{O}}_{\\text{4}}}}\\limits^{ + 7}  \\to \\mathop {{\\text{Mn}}{{\\text{O}}_{\\text{2}}}}\\limits^{ + 4} :3\\,{{\\text{e}}^ - }\\,{\\text{gained}}$<br>$\\mathop {{\\text{KMn}}{{\\text{O}}_{\\text{4}}}}\\limits^{ + 7}  \\to  + \\mathop {{\\text{Mn}}}\\limits^{ + 2} \\,\\,:\\,\\,5\\,{{\\text{e}}^ - }\\,{\\text{gained}}$<br>$\\mathop {{\\text{KMn}}{{\\text{O}}_{\\text{4}}}}\\limits^{ + 7}  \\to \\mathop {{\\text{Mn}}}\\limits^{ + 3} {({\\text{OH}})_3}:\\,\\,4\\,{{\\text{e}}^ - }\\,{\\text{gained}}$<br>$\\mathop {{\\text{KMn}}{{\\text{O}}_{\\text{4}}}}\\limits^{ + 7}  \\to \\mathop {{\\text{MnO}}_4^{2 - }}\\limits^{ + 6} :\\,\\,1\\,{{\\text{e}}^ - }\\,{\\text{gained}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
