(27497,'chemistry',68,1116,2675,'${\\text{C}}{{\\text{H}}_{\\text{3}}}{\\text{OH}}\\xrightarrow[{({\\text{i}}){\\text{Rh}};\\Delta }]{{{\\text{(i)X}}}}{\\text{C}}{{\\text{H}}_{\\text{3}}}{\\text{COOH}}$. In this reaction \' $$\\mathrm{X}$$ \' is','[{"text": "$$\\\\mathrm{CO}_{2}$$", "isCorrect": false}, {"text": "$$\\\\mathrm{CO}$$", "isCorrect": true}, {"text": "$$\\\\mathrm{MgO}$$", "isCorrect": false}, {"text": "$$\\\\mathrm{C}$$", "isCorrect": false}]',1,'${\\text{C}}{{\\text{H}}_{\\text{3}}}{\\text{OH + CO}}\\xrightarrow[{{\\text{Rh, high pressure}}}]{}{\\text{C}}{{\\text{H}}_{\\text{3}}}{\\text{COOH}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(27499,'chemistry',67,1074,2562,'Substrate of Dow\'s process for the manufacture of Phenol is','[{"text": "Chlorobenzene", "isCorrect": true}, {"text": "Benzenediazonium chloride", "isCorrect": false}, {"text": "Benzenesulphonic acid", "isCorrect": false}, {"text": "Cumene", "isCorrect": false}]',0,'${{\\text{C}}_{\\text{6}}}{{\\text{H}}_{\\text{5}}}{\\text{Cl}}\\xrightarrow[{{\\text{ pressure }}}]{{{\\text{NaO/}}\\Delta }}{{\\text{C}}_{\\text{6}}}{{\\text{H}}_{\\text{5}}}{\\text{OH}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
